INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('princess-minerva', 42287, '1992-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7cnt.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scpg6s.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Princess Minerva', 'Princess Minerva is a role-playing video game developed and published by Riverhillsoft for the NEC PC-9801 in 1992 in Japan only. An original video animation by Group TAC was originally released by Toho in May 1995 in Japan; it was later released also in the United States. The extended franchise also includes a manga series, an illustrated serial novel, and other media.' FROM games WHERE igdb_id = 42287 ON CONFLICT (game_id, language_code) DO NOTHING;
