INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('alice-no-yakata-ii', 299798, '1992-07-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa4xl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scvqy9.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alice no Yakata II', 'An Alice Soft fan-disc containing four short games and varied extra content, such as being able to listen to the complete soundtrack of all their previous games. The following games are part of this collection: 1. A mini-RPG set after the events of Rance 3. You take the control of Patton as he tries to beat an M Land attraction during Hunty''s absence. 2. A short adventure game about a pair policewomen trying to solve the case of a serial rapist. 3. After the disappearance of Rance at the end of Rance 3, the princess of Leazas Lia takes her frustrations out on monsters she takes captive. You play as a valiant Okayu Fever as he assaults Leazas castle to save the captive monsters. The game inherits the Rance 3 battle system and is composed of a set of preset encounters. 4. A quiz game in which you get a naked CG or a short ero scene with an Alice Soft heroine after succesfully answering the questions. Includes heroines from the Rance series, Toushin Toshi and D.P.S. SG Set 2.' FROM games WHERE igdb_id = 299798 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 299798 AND ge.slug = 'visual-novel' ON CONFLICT DO NOTHING;
