INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crystal Mines II', 'Great treasure still lies deep in the abandoned Crystal Mines. But over the years, underground demons have made them deadly. Guide your robot through the mines, destroying demons and gathering great wealth. Or fail, and become history. Crystal Mines II is an update of the gameplay in its predecessor; in a nutshell, overhead puzzle-solving best described as Chip''s Challenge meets Boulder Dash, with a touch of real-time elements thrown in.' FROM games WHERE igdb_id = 46921 ON CONFLICT (game_id, language_code) DO NOTHING;
