INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Double Dragon', 'Double Dragon: The Revenge of Billy Lee is a beat ''em up game developed and published by Virgin Interactive in 1993 for Sega''s Game Gear handheld console. It is a unique entry in the series, exclusive to the console, and implements many elements not seen in most other installments of the franchise. The game was entirely developed by Virgin Interactive, with no involvement from Technōs other than its licensing; as such, it implements many aspects not seen in most other installments of the Double Dragon franchise, such as the ability to use firearms. Furthermore, in contrast to the gameplay style and aesthetics already established by previous games, the Game Gear version takes a unique approach that is more similar to other beat ''em ups, such as the Streets of Rage series.' FROM games WHERE igdb_id = 201322 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 201322 AND ge.slug = 'hack-and-slash-beat-em-up' ON CONFLICT DO NOTHING;
