INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('wings-2-aces-high', 42577, '1992-11-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co49k2.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wings 2: Aces High', 'The game takes place during World War 1. Choose one of the five allied fighter pilots to do battle against the Central Powers. The game consists of 20 missions with the final one culminating with a battle between the player and "The Red Baron". Missions are basically the same as in its'' predecessor Wings. There are bombing missions where you have to take out targets that were circled in an aerial photograph, strafing runs where you get to blast anything that you fancy blasting with an unlimited supply of ammo, and of course the main part: dogfights in the sky. If a mission is completed successfully, the player can power up the successful pilot in four skill categories: flying, shooting, mechanics, and stamina. A failed mission can lead to either a dishonorable discharge or death for the pilot.' FROM games WHERE igdb_id = 42577 ON CONFLICT (game_id, language_code) DO NOTHING;
