INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'F-16 Renegade', 'F-16 Renegade: The action in this game consists of flying a jet and shooting other jets. However, the perspective alternates from overhead scrolling (odd levels) to 3rd person view from behind the jet (even levels). Powerups come in the form of stronger weapons, smart bombs, and extra lives. The game also features a 2-player competitive mode.' FROM games WHERE igdb_id = 66706 ON CONFLICT (game_id, language_code) DO NOTHING;
