INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('shogun-warriors', 39584, '1992-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8hg8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc6cyx.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shogun Warriors', 'Shogun Warriors plays similarly to some other 2D versus fighting games during its release, which the player''s character fights against his or her opponent in best two-out-of-three matches in a single player tournament mode with the computer or against another human player. It is controlled with an 8-way joystick and 4 buttons that perform weak and strong versions of punches and kicks. In one player mode, after selecting a character, the arcade randomly selects an opponent. The opponent order goes randomly and always leaves the last four bosses in a certain order. Some characters stabbed by ones armed with katanas or other sharp weapons can cause blood to spurt out, which became popularized a few months later by Midway''s Mortal Kombat. The main unique feature of Shogun Warriors is its "grabbing system". When the player is grabbed by the opponent, the grabber must move the joystick left and right to make it more difficult for his opponent to escape, while the one being grabbed must rapidly press any or all buttons to make it easier to escape.' FROM games WHERE igdb_id = 39584 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 39584 AND ge.slug = 'fighting' ON CONFLICT DO NOTHING;
