INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hexuma: Das Auge des Kal', 'Hexuma: Das Auge des Kal sends you into an old, supposedly haunted mansion, which turns out to be a gateway to six different periods in Earth’s history. Travel from the age of dinosaurs to the distant future and bring back six crystal shards to battle the sinister god Kal.' FROM games WHERE igdb_id = 84271 ON CONFLICT (game_id, language_code) DO NOTHING;
