INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Momotaro Dentetsu II', 'Super Momotaro Dentetsu II is a video game in the Momotaro Dentetsu series of board game-style video games, genre released in 1991 by Hudson Soft for the PC Engine, Game Boy and Super Famicom. The game was only released in Japan. The game was also included in the list of games available for the TurboGrafx-16 Mini in March 19, 2020.' FROM games WHERE igdb_id = 38067 ON CONFLICT (game_id, language_code) DO NOTHING;
