INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('crazy-cars-iii', 12552, '1992-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3d5q.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/xibuewihqqj3tnffc2n7.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crazy Cars III', 'The game is essentially an upgrade from Titus Interactive previous entry in the Crazy Cars series, Crazy Cars III. It adds a two player mode and a few more options. The objective of the game is to become the undisputed champion of illegal races in the U.S.A.. To do so, the player must race against a group of computer controlled opponents in a variety of illegal races across the country. The races are divided into three leagues, each one with increasingly harder opponents, and the player needs to regularly upgrade his Lamborghini Diablo in order to keep him above the rest of drivers, by using the money from bets as well as the bonuses obtained when finishing races in the first place. The races themselves take place in a variety of scenarios (mountain roads, the desert, urban settings) and they include weather conditions such as rain and snow. At the end of each league, and in order to be able to join the next one, the player has to go through a "challenge", consisting of a timed race in a highway infested with trucks. Despite the game obtaining mostly positive reviews, a major source of complaints came from the saving system. Players are allowed to save their progress once every four races. Since the game requires the player to always finish in first place in order to progress further into the game, this means players needed to win four races in a row before saving their progress.' FROM games WHERE igdb_id = 12552 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 12552 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
