INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metal & Lace: The Battle of the Robo Babes', 'Metal & Lace is an anime-style fighting game based on the Japanese-only Ningyō Tsukai, with a different storyline and enhanced gameplay. In this game, you can choose between various robot models and send them into battles. All models have different names and attributes: strength, speed, etc. You can also visit shops and upgrade your mechs. Your reward is usually erotic pictures of the defeated girls.' FROM games WHERE igdb_id = 50271 ON CONFLICT (game_id, language_code) DO NOTHING;
