INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('u235', 122637, '1992-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1r31.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc75w5.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'U235', 'U235 is a puzzle board game. The game starts when Galactic Federation sends a secret agent to the planet Umhar. The aim is to neutralize the nuclear threat. To accomplish the mission the player must join together simultaneously two or more of the same elements indicated on the right side of the screen. The element moves in the indicated direction until it is stopped by another element or the edge of the board. The player may use many useful elements, such as mirrors (reflecting laser beam), bombs or detonators (destroying various barriers). However certain elements should not be brought into contact, for example the ball smashes the mirror and the bomb blows up if collides with the board edge.' FROM games WHERE igdb_id = 122637 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 122637 AND ge.slug = 'puzzle' ON CONFLICT DO NOTHING;
