INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Menacer', 'The Menacer 6-Game Cartridge is a cartridge containing six light gun games for use with the Sega Menacer. The Menacer came bundled with this cartridge, and predictably it is not compatible with any other Mega Drive peripheral. Included games: Pest Control Space Station Defender Ready, Aim, Tomatoes! Whack Ball Front Line Rockman''s Zone' FROM games WHERE igdb_id = 45599 ON CONFLICT (game_id, language_code) DO NOTHING;
