INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cyberblast', 12558, '1992-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/kqfacruiisrazdqu5eur.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/b1yubscwwtprquargyv0.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cyberblast', 'More to shoot, dodge, and grab than in any arcade hit! The Trans-universal Portal experiment in our solar system is out of control. Unless you complete your mission, our world will be engulfed by an expanding rip in space. As the coalition''s top trouble shooter, you have been elected to save the trans-universe. They fit you with powerful cybernetics and launch you on your way. Now the Cyberblast is up to you! Your mission...to survive Fastrax Laboratories and to find the missing computer chip that controls our future. By accomplishing this mission, you will seal the portal between the trans-universe before it''s too late! The fate of our future rides on your reflexes, skill and total courage! Action packed arcade! Excellent sound effects as you wind your way through 64 action-packed levels- the clock is ticking and each level is more difficult to solve than the last.  Discover ID cards, magnets, maps, zappers, bombs, and grenades to help you destroy the enemies and walls that block your path. Dodge or destroy over 20 different size enemies- drones, seekers, bubblers, guardians, launchers, and gyros that dance, bounce, spin, and shoot. Watch for poisons, or make a quick search for a chemical cure- your enemies aren''t just creatures who inhabit the lab. Compete with a friend- two player simultaneous mode.' FROM games WHERE igdb_id = 12558 ON CONFLICT (game_id, language_code) DO NOTHING;
