INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Northern Crossroads', 'Northern Crossroads is a free, text-based multiplayer RPG that’s been live since 1992. It’s classic Diku-style hack-and-slash: explore 400+ areas (~40k rooms), fight thousands of mobs, level and gear up, and team with others. No graphics—just depth, challenge, and a loyal community that loves discovery and progression. Play via modern MUD clients or Grapevine; direct connect: ncmud.net:9000.' FROM games WHERE igdb_id = 363348 ON CONFLICT (game_id, language_code) DO NOTHING;
