INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Phantasy Star Adventure', 'This game is a Japanese-style adventure game set in the Phantasy Star universe. The player interacts with the game world by choosing available options such as "See", "Talk", "Move", etc. There are a few puzzles to solve and a few encounters with hostile characters (in a "pseudo-RPG" turn-based fashion), but the largest part of the game is dedicated to exploration and dialogue with the characters.' FROM games WHERE igdb_id = 45253 ON CONFLICT (game_id, language_code) DO NOTHING;
