INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('lord-monarch--1', 356968, '1992-10-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa64j.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3vvm.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lord Monarch', 'The Super Famicom version of Lord Monarch additional themes in addition to the medieval Europe theme. There is a futuristic theme with robots, a fast food theme with French fries and soft drinks attacking health food, a Three Kingdoms era theme, and a fairy-tale theme. The game is automatically paused until someone presses the Start button, so there is unlimited time for making alliances in the Super Famicom version—until the start button is pressed. The Super Famicom version of Lord Monarch was one of the few games to support the Super Famicom mouse. A later version of the game was broadcast exclusively for Japanese markets via the Super Famicom''s Satellaview subunit under the name BS Lord Monarch and was view-limited.' FROM games WHERE igdb_id = 356968 ON CONFLICT (game_id, language_code) DO NOTHING;
