INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hello-kitty-no-hanabatake', 3688, '1992-12-11', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7h6t.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scputw.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hello Kitty no Hanabatake', 'Hello Kitty no Hanabatake is a children''s platform game developed by Character Soft, a video game publishing subsidiary of Sanrio, for the Nintendo Family Computer. It was released on December 11, 1992 exclusively in Japan. During the course of this video game, Hello Kitty must water all the flowers in each stage while avoiding the many animals and insects. Kitty''s ribbon always stays on the left side of her ear; even if the player changes the orientation of the character. She can defend herself with the use of a large mallet. Running into enemies will make her cry, which causes Kitty to get angry and lose a life. Points in the game are collected as money for the cash register. Allowing the time limit to expire will also cause the player to lose a life. However, there are infinite continues and losing the game score is the only penalty for "game overs." There are 18 stages in the game and the game does not repeat itself after the 18th stage. While the second half of the game is more difficult then the first nine levels, they can be cleared once the player is accustomed to the game controls.' FROM games WHERE igdb_id = 3688 ON CONFLICT (game_id, language_code) DO NOTHING;
