INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tamashii no Mon: Dante no Shinkyoku yori', 'Tamashii no Mon Dante no Shinkyoku yori is a side-scrolling adventure game with platforming elements. The game''s events are a distilled portrayal of the Divine Comedy, an epic poem created by Dante Alighieri depicting his journey through the nine circles of Hell to reunite with his childhood love, Beatrice.' FROM games WHERE igdb_id = 139107 ON CONFLICT (game_id, language_code) DO NOTHING;
