INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Ball Z: Gekitou Tenkaichi Budoukai', 'Dragon Ball Z: Gekitou Tenkaichi Budoukai is the first fighting video game based on Dragon Ball Z. The game was unique in that it came with a special card reader attachment, the Datach Joint Rom System, which requires several special cards to be swiped in order to add characters and items in the game.' FROM games WHERE igdb_id = 2578 ON CONFLICT (game_id, language_code) DO NOTHING;
