INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('overkill', 46704, '1992-11-11', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1v29.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc75ez.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'OverKill', 'Overkill is a vertical scrolling shooter that was released by Epic Games and Precision Software Publishing in 1992. The game was designed and developed by Tech-Noir Productions and Ste Cork. Overkill was Epic''s first vertical shooter. The game was lacking some of the technology that other top shareware games of the time had, such as Jill of the Jungle, ID Software''s Commander Keen, and Apogee''s Duke Nukem. It boasted EGA graphics, PC speaker sound effects, support for a joystick, and a General MIDI musical track. While the game did sell a considerable amount of copies, it was quickly overshadowed by later vertical shooters such as Raptor: Call of the Shadows, Major Stryker, and Tyrian. There are two versions of the game, the shareware version, and the commercial version. The shareware version allows the user to play planets one and two, while the commercial version grants access to all six planets.  As of July 23, 2008 the game is available as freeware.' FROM games WHERE igdb_id = 46704 ON CONFLICT (game_id, language_code) DO NOTHING;
