INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Acid Drop', 'A falling block game similar to Columns. The object of the game is to create a horizontal or vertical line of three or more blocks of the same color, which will then disappear. The remaining blocks will fall down, but won''t disappear if they form another line. Every 10,000 points a special block will appear (the Acid Drop) which removes three columns of blocks and marks the beginning of the next level.' FROM games WHERE igdb_id = 11111 ON CONFLICT (game_id, language_code) DO NOTHING;
