INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fire & Ice: The Daring Adventures of Cool Coyote', 'Fire & Ice: The Daring Adventures of Cool Coyote is a platform game released in 1992 for the Amiga and later ported to other systems. Players control Cool Coyote, navigating levels filled with enemies, hazards, and collectible items. The objective is to collect key pieces from defeated enemies to unlock the exit of each stage. Levels are set in various themed environments, each with distinct challenges and obstacles' FROM games WHERE igdb_id = 12099 ON CONFLICT (game_id, language_code) DO NOTHING;
