INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cell War', 'Cell War is a shareware strategy game that can be played against either the computer of another human player. It is a turn based game; when each player has completed their turn the game board is updated. When both players pass the game is over and the score is calculated with the winner being the player with the highest average number of cells throughout the game.' FROM games WHERE igdb_id = 176074 ON CONFLICT (game_id, language_code) DO NOTHING;
