INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Knuckle Heads', 'Up to four players must choose control for six different characters from: the United States, the game''s home country of Japan, Greece, China, Norway, and Brazil in what is described as "America''s hottest new game show" on the flyer; they all have different special weapons, moves, and catchphrases, and the show will move to each of the characters'' respective home towns (Honolulu, Kyoto, Athens, Hong Kong, Lillehammer and Sao Paulo) for each successive round.' FROM games WHERE igdb_id = 39588 ON CONFLICT (game_id, language_code) DO NOTHING;
