INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Quest of Agravain', 'A long time ago, Lord Agravain roamed the land of Riva in his quest for the Elixir of Youth, the only hope for the all the ageing knights. The Quest of Agravain is a platform game where the player controls a medieval knight armed with a sword. The main objective is to reach the exit door at the top of each level.' FROM games WHERE igdb_id = 74006 ON CONFLICT (game_id, language_code) DO NOTHING;
