INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jump', 'The player controls an electromechanical robot that walks along a brick wall and jumps over it. A line of enemies approaches it from the bottom of the screen in a vertical direction, while the bomb floats horizontally in the center. Enemies can be eliminated by jumping over the wall, which causes a brick to fall. The number of jumps is equal to the number of bricks from the bottom of the wall to the robot.' FROM games WHERE igdb_id = 272304 ON CONFLICT (game_id, language_code) DO NOTHING;
