INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ultraman Club: Tatakae! Ultraman Kyoudai!!', 'Ultraman Club: Tatakae! Ultraman Kyoudai!! is a 2D top-down single screen arcade game, based on the superhero Ultraman, with chibi, anime-style graphic. The player controls one of 8 versions of Ultraman. Gameplay is very simple - Ultraman must kill all enemies on screen. He has two types of attack - one is very short, but has basically unlimited ammo, & the second has better range, but is very limited. Fallen enemies drop various bonuses (like extra life or bombardment special moves), & Ultraman can pick them up.' FROM games WHERE igdb_id = 40519 ON CONFLICT (game_id, language_code) DO NOTHING;
