INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jill of the Jungle: Jill Goes Underground', 'Jill of the Jungle is a platform sidescroller which was released during the same period as Commander Keen and Duke Nukem. Players play as an Amazon woman who can use various types of weapons and enhancements as she progresses through levels slaying monsters and finding keys. The first episode in the trilogy (Jill of the Jungle) contains 15 playable levels, including a bonus level, each of which can be entered from an overworld resembling another level. This second episode uses 20 sequential levels without an overworld. (Wikipedia)' FROM games WHERE igdb_id = 50338 ON CONFLICT (game_id, language_code) DO NOTHING;
