INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('joshua-and-the-battle-of-jericho', 46186, '1992-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8el7.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Joshua & The Battle of Jericho', 'Crystal Mines is a 1989 unlicensed puzzle game for the NES by Color Dreams. When they established Wisdom Tree, they repackaged the game twice: in 1991 as Exodus: Journey to the Promised Land and in 1992 as Joshua & The Battle of Jericho, with Joshua labeled a sequel to Exodus. These two versions would be remade for the Sega Mega Drive in 1993 and 1994, respectively. Though the games do have a TMSS check, they will only do the $A14000 write if they detect the region of the console they are running on as US — therefore, the games will only boot on either any US Mega Drive or on any other Model 1 Mega Drive without TMSS (making that a partly useless form of region lockout). Gameplay of both versions is identical: you are the main character (Moses or Joshua, respectively) and you must collect all the bags with M on them (Joshua: coins with $ on them) scattered throughout each maze. A and C shoot; you can hold them down for rapidfire. Shooting destroys blockades and enemies. Once all the M bags are gathered, find the exit to move on to the next level. In between each level, you must answer a bunch of questions related to the story of the Bible of the game''s theme; getting them wrong appears to be inconsequential to the outcome of the game (this needs investigation).' FROM games WHERE igdb_id = 46186 ON CONFLICT (game_id, language_code) DO NOTHING;
