INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kawa no Nushi Tsuri: Shizen-ha', 'Like other games in the River King series, this game revolves around a hero and his sister. This time, the sister went out to catch a fish that was essential for their village''s prosperity, but hasn''t returned. The quest for bigger fish is therefore combined with the quest for the lost sister, and the hero equips weapons and rods to aid him in both tasks...' FROM games WHERE igdb_id = 20512 ON CONFLICT (game_id, language_code) DO NOTHING;
