INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Ball Z III: Ressen Jinzou Ningen', 'Dragon Ball Z III: Ressen Jinzou Ningen is the sequel of Dragon Ball Z II: Gekishin Freeza. The game starts off in the Frieza Saga as Super Saiyan Goku fighting Frieza, and it ends in the Imperfect Cell Saga in the battle of Piccolo against Imperfect Cell. The game also features characters from the movie Dragon Ball Z: Cooler''s Revenge. It is the first game in the Gokuden series where power levels are not stated.' FROM games WHERE igdb_id = 48680 ON CONFLICT (game_id, language_code) DO NOTHING;
