INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arabian Fight', 'Arabian Fight is a scrolling beat ''em up video game released in arcades by Sega in 1992 (the displayed copyright year is 1991). Running on the Sega System 32 arcade system, the game displays pseudo-3D sprite-scaling graphics and supports cooperative multiplayer for up to four players.' FROM games WHERE igdb_id = 39362 ON CONFLICT (game_id, language_code) DO NOTHING;
