INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jim Power in Mutant Planet', 'Jim Power in Mutant Planet is a platform game designed by Digital Concept and published by Loriciel for the Amiga, Atari ST and Amstrad CPC in 1992. The game features several contrasting modes of gameplay, including side-view platforming, top-view, and horizontal shoot ''em up. Jim Power in Mutant Planet was also released for the TurboGrafx-CD in 1993 exclusively in Japan.' FROM games WHERE igdb_id = 14777 ON CONFLICT (game_id, language_code) DO NOTHING;
