INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('can-can-bunny-premiere', 108895, '1992-07-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8eur.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sce729.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Can Can Bunny Premiere', 'In this game, the player assumes the role of an ordinary Japanese young man who works in a restaurant. One day he comes home and finds seven strange creatures sitting at his table and discussing something you have no clue about. But before you decide to throw the uninvited guests out of your apartment, a beautiful green-haired woman appears. This is the goddess Swatty, and she has power over the Seven Lucky Gods, which the mysterious seven creatures turn out to be. Swatty feels pity for the lonely hero, and decides to help him to find a girlfriend. Can Can Bunny Premier is the fourth installment in the Can Can Bunny series. Compared to its predecessors, it is the most pure Japanese-style adventure, without the strategy parts of the previous game. The player chooses menu commands ("Look", "Talk", etc., as well as context-sensitive commands and dialogue choices) in order to advance the game. At several points it is possible to branch the story line, which mostly influences the amount of success the hero has had with a girl.' FROM games WHERE igdb_id = 108895 ON CONFLICT (game_id, language_code) DO NOTHING;
