INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zyconix', 'Puzzle game where you match three tiles either horizontally or diagonally by dragging them in place. The game speeds up and adds more coloured tiles the further you get into the game and the game ends when the tiles reach the top of the screen.' FROM games WHERE igdb_id = 84210 ON CONFLICT (game_id, language_code) DO NOTHING;
