INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('marky-mark-and-the-funky-bunch-make-my-video', 46416, '1992-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2qne.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scj0yz.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marky Mark and the Funky Bunch: Make My Video', 'Make My Video: Marky Mark and the Funky Bunch is a video game based on real-time editing of music video footage. The setup is that a brother and sister pair is arguing about what would make the best Marky Mark video. Since they can not agree, they enlist help from some other people: A boxer and his trainer, a trio of teenage girls, the members of a garage band, and their parents. Each group has their ideas about what an ideal Marky Mark video should or should not contain. The specifications normally come in the form of a set of pictures they either do or don''t want to see, and perhaps some effects. The game has three Marky Mark videos from which to choose: "Good Vibrations", "I Need Money", and "You Gotta Believe".' FROM games WHERE igdb_id = 46416 ON CONFLICT (game_id, language_code) DO NOTHING;
