INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Biff', 'You must control Biff around the jungle, performing tasks to please your mother. Tasks should be completed in order , to help you with this Tthe object that is flashing is the object to be used next.. There are also comments in the display box that give you hints on what to do next.' FROM games WHERE igdb_id = 13393 ON CONFLICT (game_id, language_code) DO NOTHING;
