INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Phantasy Star Gaiden', 'Phantasy Star Gaiden is a Sega Game Gear released as part of the Phantasy Star franchise. It was only released in Japan. Phantasy Star Gaiden plays pretty much like any other Phantasy Star starting with the second game: both towns and dungeons are in top-down view, the turn-based battles are viewed from first-person perspective. The gameplay is standard console-style RPG: you should fight random enemies, gain experience and gold, buy better equipment, visit many towns and dungeons, etc.' FROM games WHERE igdb_id = 45252 ON CONFLICT (game_id, language_code) DO NOTHING;
