INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('megami-tensei-gaiden-last-bible--2', 49830, '1992-12-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9hrb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sct03i.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Megami Tensei Gaiden: Last Bible', 'A mystical force known as Gaia permeates every aspect of the planet. Those who are aware of the force can manipulate it to do their bidding. While most use Gaia for good, there are those who would use it for evil. You take the role of El, who must journey around the world in hopes of stopping those who want to use Gaia for evil. Along the way, you will encounter new friends that will aid you in the quest. Ultimately, you will encounter monsters, and if you''re lucky, you''ll be able to convince the monsters to join you. When a monster has joined the party, it can be summoned to help in battle. While the monster will not gain experience, it can be combined with other creatures to create a more powerful monster. Try to keep Gaia pure and evil free in REVELATIONS: The Demon Slayer.' FROM games WHERE igdb_id = 49830 ON CONFLICT (game_id, language_code) DO NOTHING;
