INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Sword of Hope II', 'The Sword of Hope II is a role-playing game. Take on the role of young Prince Theo of Riccar and embark on a mission to find the truth behind a mystery that is threatening the kingdom. The key to solving the numerous puzzles and gimmicks is the use of commands like "look," "open" and "hit." You''ll encounter many places and items during the adventure, plus some friends waiting to lend a hand along the way.' FROM games WHERE igdb_id = 10947 ON CONFLICT (game_id, language_code) DO NOTHING;
