INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Pack Rat', 'The Pack Rat is a DOS platformer released in 1992. The goal of The Pack Rat is to complete levels while collecting coins and wedges of cheese and avoiding environmental obstacles such as water and light bulbs. The pack rat contains single-player and two-player hot seat modes along with a block based level editor however, progress in The Pack Rat cannot be saved.' FROM games WHERE igdb_id = 73089 ON CONFLICT (game_id, language_code) DO NOTHING;
