INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('yokoyama-mitsuteru-sangokushi', 37759, '1992-06-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4cn3.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yokoyama Mitsuteru: Sangokushi', 'Yokoyama Mitsuteru Sangokushi is a strategy game based on the anime and manga of the same name by manga artist Yokoyama Mitsuteru. The name simply means "Yokoyama Mitsuteru''s version of Sangokushi", Sangokushi being the Japanese name for the Chinese literary classic Romance of the Three Kingdoms. The manga and anime retell the story of the book, with the game focused on this retelling. During the game''s development the anime adaptation was in full swing, so the game was intended to be a companion piece. This was a standard practice of Bandai at the time (Angel was a game publisher subsidiary of the toy giant), as was hiring freelance developers like TOSE to develop for them. The game is a standard turn-based strategy war sim in the vein of Koei''s much more prolific Romance of the Three Kingdoms series. The player and the AI-controlled rival kingdoms select actions that include diplomacy, combat and domestic matters such as farming and trade, with the ultimate goal being to wrest control over the rest of China from the other two kingdoms. The game was followed up with two sequels: a standard sequel in Yokoyama Mitsuteru Sangokushi II and the board game spin-off Yokoyama Mitsuteru Sangokushi Bangi.' FROM games WHERE igdb_id = 37759 ON CONFLICT (game_id, language_code) DO NOTHING;
