INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Double Moon Densetsu', 'Double Moon Densetsu is a 1992 role-playing video game for the Family Computer published by Masaya. It is based on an earlier play-by-mail RPG also titled Double Moon Densetsu, serialized in Marukatsu Famicom and eventually Marukatsu Super Famicom; in addition to this computer game, there was also a tabletop RPG system produced based on the work. A deity named Fatima created a world with two different continents; that divided the world of sorcery from the world of swordsmanship. An evil demon plans to destroy this world by bringing forth a dark dragon from a demonic dimension.' FROM games WHERE igdb_id = 48522 ON CONFLICT (game_id, language_code) DO NOTHING;
