INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dune MUD', 'Dune Mud is a classic multiplayer online text adventure game (MUD) based in Frank Herbert''s DUNE Universe. Since 1992 Dune has been the LP MUD of choice for several generations of amazing players. Create a character, join one of ten guilds, and explore the 30,000+ game rooms. Enjoy opt-in PK and numerous in-game quests. Friendly players! Social atmosphere! Passionate playerbase! Discord integration! Active coding staff!' FROM games WHERE igdb_id = 228880 ON CONFLICT (game_id, language_code) DO NOTHING;
