INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Break Time: The National Pool Tour', 'Break Time: The National Pool Tour is a pocket billiards (pool) video game released for the Nintendo Entertainment System. There are four unique challenges in the game, eight-ball, nine-ball, rotation and straight pool. All four are allegedly played according to the professional (i.e. world standardized) rules.' FROM games WHERE igdb_id = 48103 ON CONFLICT (game_id, language_code) DO NOTHING;
