INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hanjuku Hero: Aa Sekai yo Hanjuku Nare', 'Hanjuku Hero: Aa, Sekai yo Hanjuku Nare...! is the second game in the series. The Egg Monsters featured in the game are parodies of Final Fantasy IV characters. The game was re-released on the WonderSwan Color in 2002. This version features a graphical overhaul and twelve new summons.' FROM games WHERE igdb_id = 37441 ON CONFLICT (game_id, language_code) DO NOTHING;
