INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Comanche: Maximum Overkill', 'Comanche: Maximum Overkill is a helicopter combat simulator that showcases NovaLogic''s groundbreaking Voxel engine, rendering lifelike terrain and objects surpassing contemporary polygon-based graphics. Players control the experimental RAH-66 Comanche light attack helicopter through over 20 scripted campaign missions. The game features a simplified flight model and increased helicopter durability, prioritizing accessible gameplay over strict realism. Weapons are portrayed with enhanced accuracy and power, creating intense combat scenarios. As the first in NovaLogic''s series of helicopter simulations, Comanche: Maximum Overkill combines innovative graphics technology with engaging gameplay, offering players a unique and visually impressive military combat experience for its time.' FROM games WHERE igdb_id = 7494 ON CONFLICT (game_id, language_code) DO NOTHING;
