INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tecmo NBA Basketball', 'This basketball game is very similar to Tecmo Super NBA Basketball with the main difference being their rosters. The game has 27 NBA teams with a roster of 324 Players. Each player has a rating for his shooting ability, stamina, jumping power, running speed, stealing ability, and blocking ability. The game allows for pre-season and season modes. In the season modes the game tracks team & player statistics throughout the season.' FROM games WHERE igdb_id = 48226 ON CONFLICT (game_id, language_code) DO NOTHING;
