INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ex-Mutants', 'Action game based on the Ex-Mutants comic book series by Malibu Comics. Leaping from the pages of the popular comic book come the Ex-Mutants. Choose Shannon or Ackroyd as you weave your way through the nuclear wasteland to battle the minions of the evil Sluggo and restore the human race!' FROM games WHERE igdb_id = 36738 ON CONFLICT (game_id, language_code) DO NOTHING;
