INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sherlock Holmes: Consulting Detective Vol. II', 'The same structure brings a familiar look, inviting to channel all attention to the task of solving mysteries: your intelligence, skills and patience are required to find clues by listening to people, observing details, or even reading the London Times - but don''t let yourself be misguided by a wrong hint.' FROM games WHERE igdb_id = 5436 ON CONFLICT (game_id, language_code) DO NOTHING;
