INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Power Factory Featuring C+C Music Factory', 'The first of Digital Pictures'' "Make My Video" line has you "editing" three of C + C Music Factory''s most famous songs - "Gonna Make You Sweat," "Things That Make You Go Hmm..." and "Here We Go Let''s Rock & Roll." The plot puts you inside the music factory of the game''s name, where two linemen sweat and toil under the oppressive thumb of a wheelchair-bound corporate executive. Video discs literally roll down an assembly line while C + C record their sounds behind three closed doors. You are asked to help out in editing these videos, appease the corporate masters, and lift the burden from everyone.' FROM games WHERE igdb_id = 5420 ON CONFLICT (game_id, language_code) DO NOTHING;
