INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Thunder Pro Wrestling Retsuden', 'Thunder Pro Wrestling Retsuden is an entry in Human''s Fire Pro Wrestling series. The game is a typical wrestling game presented in an isometric view with the entire ring visible on screen at once. Each button combination does something different depending on what situation you are in at the time. A North American release under the name Jesse "The Body" Ventura Wrestling Superstars was planned by DreamWorks, but was never released for unknown reasons.' FROM games WHERE igdb_id = 46165 ON CONFLICT (game_id, language_code) DO NOTHING;
