INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle Blaze', 'Battle Blaze is a weapon-based fighting game from 1992, set in a medieval fantasy world. Players choose warriors to duel in story and versus modes. While offering an interesting concept, the game was hindered by stiff controls and a limited moveset compared to other fighting games of its era.' FROM games WHERE igdb_id = 42629 ON CONFLICT (game_id, language_code) DO NOTHING;
