INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('lady-sword-ryakudatsusareta-10-nin-no-otome', 42050, '1992-07-13', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6xio.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sct0p2.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lady Sword: Ryakudatsusareta 10-nin no Otome', 'An unlicensed eroge dungeon-crawler RPG developed by Games Express for the PC Engine in 1992. Lady Sword is an RPG of the Wizardry/Eye of the Beholder/Etrian Odyssey mold. An unnamed swordsman delves deep into a cursed labyrinth in order to rescue a group of abducted women from their monstrous captors. Throughout the early stages, the player character randomly bumps into other NPCs who dole out advice and tips. Upon successfully clearing each floor, the player is presented with a nude image of the rescued women; this is the extent of the eroge element. The game was developed by Games Express, a sobriquet for Hacker International: a company which primarily developed and published unlicensed games for the PCE and Famicom.' FROM games WHERE igdb_id = 42050 ON CONFLICT (game_id, language_code) DO NOTHING;
