INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Final Lap 3', 'Final Lap 3 is the next sequel of the Final Lap racing game series. It is similar to the previous game, once again offering four tracks, though they''re all new: the Silverstone Circuit, the Paul Ricard Circuit, the Barcelona-Catelunya Circuit, and the Enzo Ferrari Circuit. Like the previous game, it was an arcade exclusive and runs on Namco System 2 hardware. Up to eight players can play simultaneously when four two-player cabinets are linked together.' FROM games WHERE igdb_id = 337555 ON CONFLICT (game_id, language_code) DO NOTHING;
