INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Quiz no Hoshi', 'Quiz no Hoshi is a trivia game with several gameplay modes; the main one is called "Heart of Stone" and is a story-driven series of quiz encounters with strategy board game elements. The plot involves a kidnapping of a little girl by the mafia, and the attempts of a boy named Hoshimaru to rescue her, all the while escaping from an impending apocalypse.' FROM games WHERE igdb_id = 371105 ON CONFLICT (game_id, language_code) DO NOTHING;
