INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Take a Break! Crosswords', 'Take a Break! Crosswords is a collection of puzzles licensed from Dell. Volume I represents the 375 crossword puzzles from Dell Magazines, where you have to put the word, which is an answer for the certain question, in vertical or horizontal line of table. These words have common letters because of crossing and it allows to remember the word by available letters in already resolved words.' FROM games WHERE igdb_id = 76557 ON CONFLICT (game_id, language_code) DO NOTHING;
