INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Varth: Operation Thunderstorm', 'Operation Thunderstorm, engage! Varth: Operation Thunderstorm is a shoot ''em up game released by Capcom in 1992 for it''s CPS-1 Arcade board. The game is about two brave pilots take flight to save humanity from the evil DUO (Dimension Unbody Offender).' FROM games WHERE igdb_id = 39312 ON CONFLICT (game_id, language_code) DO NOTHING;
