INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('stone-age', 15378, '1992-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5tdv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sck39y.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stone Age', 'Stone Age is a charming puzzle game where players guide a cartoon dinosaur through 100 challenging cave levels. The core gameplay revolves around strategically navigating various block types, including standard platforms, movable blocks, crumbling tiles, and color-coded keys and locks. With two difficulty modes offering different time constraints, the game balances accessibility with challenge, appealing to both casual players and puzzle enthusiasts. The simple yet effective graphics complement the complex level designs, creating an engaging visual experience. The game features a robust progress system, including level passwords that allow players to return to specific stages, preserving their advancement without sacrificing challenge. A unique Jukebox feature adds to the game''s appeal, enabling players to customize their audio experience by creating playlists of the game''s tracks. This combination of strategic puzzle-solving, time management, and personalization options makes Stone Age a compelling and replayable experience that tests both reflexes and problem-solving skills across its diverse cave scenarios.' FROM games WHERE igdb_id = 15378 ON CONFLICT (game_id, language_code) DO NOTHING;
