INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hokuto no Ken 5: Tenma Ryuusei-den Ai Zesshou', 'Hokuto no Ken 5: Tenma Ryuusei-den Ai Zesshou is a role-playing video game produced by Toei Animation released on July 10, 1992 for the Super Famicom in Japan. It is the third and final RPG produced by Toei based on the Hokuto no Ken franchise, following Hokuto no Ken 3 and Hokuto no Ken 4, both for the Family Computer. Hokuto no Ken 5 features an original storyline, written once again by Hiroshi Toda with plot supervision by Buronson, set in an alternate universe from the original work''s canon where a new hero must unite the warriors of the Hokuto, Nanto, and Gento schools to defeat a common enemy.' FROM games WHERE igdb_id = 42552 ON CONFLICT (game_id, language_code) DO NOTHING;
