INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ninja Commando', 'Ninja Commando is a vertically scrolling action game released by ADK in 1992. Players choose from among three ninjas - Joe, descended from the Koga ninja; Rayar, a woman who has learned the ways of the Iga ninja; and Ryu, descendant of the famous ninja Fuma Kotaro - as they pursue the merchant of death known as Spider, who plans to use a time machine to bring havoc to the world. The battle spans seven time periods, including the Stone Age, the Egyptian era and the Japanese Civil War era.' FROM games WHERE igdb_id = 39951 ON CONFLICT (game_id, language_code) DO NOTHING;
