INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Saint Seiya Paradise: Saikyou no Senshi-tachi', 'The combat mode is in the style of RPG video games, with many levels and items going through towns and anime scenarios. The video game begins in the Galaxian Wars and ends with the combat against the god Poseidon, making their appearances minor characters like Gigas and Geist that would not be used in other video games later.' FROM games WHERE igdb_id = 60380 ON CONFLICT (game_id, language_code) DO NOTHING;
