INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Great Waldo Search', 'The pictures are slightly animated images of Waldo scenes, the player has to scroll along the long picture to survey the scape while searching for Waldo and other objects. The directional buttons control a magnifying glass and is used in order to "find" objects. Waldo''s dog Woof is also in each level and by finding him the player gets to play a small bonus game to collect points while controlling Woof on a flying carpet.' FROM games WHERE igdb_id = 48158 ON CONFLICT (game_id, language_code) DO NOTHING;
