INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Prophecy of the Shadow', 'Embark on a prophecy-driven quest in this classic fantasy RPG. Battle the encroaching Shadow Lords, navigate a world where magic is illegal, and uncover the truth behind a master''s treacherous death. Real-time combat, spell-learning, and captivating storytelling await in this post AD&D-era gem.' FROM games WHERE igdb_id = 12461 ON CONFLICT (game_id, language_code) DO NOTHING;
