INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('battle-chess-4000', 11099, '1992-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co21h7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar15ky.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle Chess 4000', 'Welcome to the chess game of tomorrow! Yesteryear''s timeless classic is now a game for all ages in Battle Chess 4000. In this box, you''ll find that the traditional chess game has rushed headlong into the future. Moving across a translucent chess board set in a futuristic, deep-space station, chess pieces become animated space-age characters, created from state-of-the-art, digitized clay models. And the moves they make will keep you in stitches. A swashbuckling space captain forgoes his blaster to wield a light saber at your mad scientist. Then, a robot rushes in to tickle the mad scientist to death... and all you can say is "check"? But for all its humor, Battle Chess 4000 is one of the strongest and most versatile chess programs on the market. With a massive opening library of more than 300,000 moves, Battle Chess 4000 can handle any level of opponent. And it learns as it plays by constantly adding strong moves to its database.' FROM games WHERE igdb_id = 11099 ON CONFLICT (game_id, language_code) DO NOTHING;
