INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dracula: The Undead', 'You must escape Dracula''s sinister castle, find the dark one and drive a stake through his heart. To escape, you must explore the castle and learn its secrets. If you fail, you will join Dracula''s brides for dinner, and guess who''s the main course! Dracula - The Undead is a video game released in 1991 for the Atari Lynx handheld system. The game is loosely based on Bram Stoker''s novel Dracula and features Bram Stoker in the story as the narrator.' FROM games WHERE igdb_id = 46920 ON CONFLICT (game_id, language_code) DO NOTHING;
