INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Traysia', 'In Traysia the player controls a young man named Roy, who lives in the town Johanna. All his life Roy has been dreaming about leaving the town and going to explore faraway lands. Now, finally, his chance has come. His uncle, a travelling merchant, is going on a journey, and Roy decides to leave with him. His girlfriend Traysia gives him a pendant, to remind him of her... will Roy be able to escape from all the dangers that await him on his long journey and to see Traysia again?' FROM games WHERE igdb_id = 46259 ON CONFLICT (game_id, language_code) DO NOTHING;
