INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('storm-master', 10853, '1992-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/wyygzodgopgfztnhj8l1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ljpkta68f4kyvzc0nnpi.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Storm Master', 'Storm Master is a 1991 video game for the Amiga, Atari ST and PC, produced by the now-defunct French developer Silmarils, which placed the player as the head of government for a fictional semi-medieval country. Similarly to most of the games produced by Silmarils, Storm Master took place on a European-fantasy world. Gameplay revolved around the governance and management of the country of Eolia in an ongoing war against its neighbour, Shaarkania, with the ultimate goal of sacking (and, by inference, destroying) all enemy cities.[1][2] The game was notable for a blend of turn-based strategy interspersed with live-action battles. This took the form of aerial battles against enemy air fleets or air defences and required the player to launch ballistic missiles against enemy ships or batteries. Other real-time elements of the game involved the player conducting a religious ceremony with the goal of increasing the natural wind energy of the nation. This element of gameplay was further enhanced by requiring the player to dispatch government ministers around the country to develop or industrialise various aspects of the state. The game was further noted by Amiga Action as having an innovative ''advance through time'' feature, allowing the player some control over the rate at which time passed in the game.' FROM games WHERE igdb_id = 10853 ON CONFLICT (game_id, language_code) DO NOTHING;
