INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('quiz-and-dragons-capcom-quiz-game', 39316, '1992-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2tg0.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Quiz & Dragons: Capcom Quiz Game', 'The far off land of Capconia lived in peace and prosperity for years thanks in part to the Knowledge Tree, a tree in which the holder of the tree''s seeds are granted infinite knowledge of the world around them. However, an evil being known as Gordian has taken a seed of the tree and has planted a Knowledge Tree of his own. Gordian has given some of the seeds to some of the dragons in the land and now, which unfortunate soul who cannot answer any of the dragon''s questions correctly will be eaten by them. The King then decides to send out four brave warriors entrusted with the knowledge of the land out to stop Gordian and end his tyranny once and for all.' FROM games WHERE igdb_id = 39316 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 39316 AND ge.slug = 'puzzle' ON CONFLICT DO NOTHING;
