INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario Teaches Typing', 'Mario Teaches Typing is one of the few licensed Mario computer titles. As the title suggests, Mario Teaches Typing was designed for improving a computer user''s typing skills. Kids with no typing experience will get the most from the program, while enjoying cute antics of Nintendo''s popular Mario brothers. All of the game''s music was sampled from Super Mario World.' FROM games WHERE igdb_id = 50335 ON CONFLICT (game_id, language_code) DO NOTHING;
