INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Soldam', 'Soldam is a puzzle game where the goal is to match soldam fruits along an entire row. The fruits drop down from the top in a 2x2 square which can be rotated. If the edge pieces match color, all of the fruits in the direction of the matching edge pieces will change their color to match. Matching edge pieces can be made horizontally, vertically, or diagonally.' FROM games WHERE igdb_id = 78225 ON CONFLICT (game_id, language_code) DO NOTHING;
