INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hokuto no Ken 6: Gekitou Denshouken - Haou he no Michi', 'Near the end of the 20th century, the world returned to a dark age ruled by power after the nuclear war. The masters of the Hokuto, Nanto, and Gento Kō Ken martial arts have staked their own pride as they wage wars against each other. The stage has been set for an epic battle between these mighty men. The battle for supremacy has begun!' FROM games WHERE igdb_id = 38264 ON CONFLICT (game_id, language_code) DO NOTHING;
