INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slicks', 'Slicks is a top down Formula 1 style racing game for the C64. This game allowed you to pit your wits against qualifying and racing other drivers in multiple races over several tracks. It allows you to race cars such as Benneton, Ferrari and Mclaren.' FROM games WHERE igdb_id = 78803 ON CONFLICT (game_id, language_code) DO NOTHING;
