INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shadowlands', 'Shadowlands is a computer game developed by Domark in 1992 for the PC (DOS), Amiga and Atari ST. Shadowlands is a fantasy role-playing game in which the player has four game characters, that the player can operate either as a squad or as independents during the course of the adventure.' FROM games WHERE igdb_id = 37128 ON CONFLICT (game_id, language_code) DO NOTHING;
