INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lucky & Wild', 'The object of the game is to stop a bunch of criminals led by the main antagonist Big Cigar from breaking laws. The plot of the game is to stop a bunch of drug dealers. The game stars 2 men. "Wild" (based on "Hutch" and "Cash"), a surfer with long blonde hair. who is the shooter. And "Lucky" (modeled after "Starsky" and "Tango"), is the driver and wields a gun.' FROM games WHERE igdb_id = 13898 ON CONFLICT (game_id, language_code) DO NOTHING;
