INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'JezzBall', 'JezzBall is a video game originally published for Microsoft Windows in 1992. The player must capture parts of a rectangular space by dividing it with horizontal or vertical lines. While each line is being drawn it must not be touched by bouncing balls. JezzBall has similarities with Qix, a 1981 arcade game.' FROM games WHERE igdb_id = 93291 ON CONFLICT (game_id, language_code) DO NOTHING;
