INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Samochodowy Wojownik', 'Samochodowy Wojownik is an arcade racing game with shooter elements. You are the driver of the police combat car - Ferrari 1200 DRX, struggling with a gang of smugglers in the suburbs. During the patrol, you will encounter the vehicles of the criminals and the criminals themselves who will try to eliminate the threat. The game is currently "Lost Media".' FROM games WHERE igdb_id = 150529 ON CONFLICT (game_id, language_code) DO NOTHING;
