INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Breakout 3000', 'Like the name suggests, Breakout 3000 is a Breakout game. So you have a screen filled with bricks, a ball and a paddle. Destroy all bricks with the ball. Use the paddle to bounce the ball back into the playfield when it''s about to leave the screen. The game offers 23 levels to play. The more levels you play, the faster will be the game, but also the more special bricks you encounter (exploding bricks, which destroys adjacent bricks; extra lives; etc.) and the more different background themes you will see.' FROM games WHERE igdb_id = 73293 ON CONFLICT (game_id, language_code) DO NOTHING;
