INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Traffic Confusion', 'Traffic Confusion is a traffic congestion simulation game where the goal is to clear the the map of cars which each has their own destination while keeping accidents and potential deaths to a minimum. Stress among the drivers will build up while they''re waiting stuck in traffic or congestion is too high etc. You lose the game if the stress level reaches its maximum point.' FROM games WHERE igdb_id = 178353 ON CONFLICT (game_id, language_code) DO NOTHING;
