INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Operation Blood', 'It is an on-rails first-person shooter released in 1992 for Atari. The player is provided with one main weapon (a rifle) and one secondary weapon (grenades) and his main goal is to kill all enemies on the screen while trying to not shoot civilians or medics. The player cannot control the camera, the screen scrolls from the right side to the left side or vice versa by itself. There are also power-ups appearing from time to time which the player can use in order to achieve victory.' FROM games WHERE igdb_id = 137566 ON CONFLICT (game_id, language_code) DO NOTHING;
