INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sports Talk Baseball', 'Players can play either exhibition, regular season, all-star, or playoff games. The game also features authentic Major League Baseball rosters for the 1991 season. Gameplay commonly features double and triple plays, and only the fastest runners in the game are capable of stealing bases. It was one of the first video games to feature individual hitting abilities for each pitcher. Classic match-ups include Texas'' Nolan Ryan versus Oakland''s lineup with such all-stars as Jose Canseco, Rickey Henderson, Dave Henderson, and Mark McGwire.' FROM games WHERE igdb_id = 46261 ON CONFLICT (game_id, language_code) DO NOTHING;
