INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Neuronics', 'Neuronics is a tile-matching puzzle game with similarities to Swap: The player is presented with a number of tiles with different symbols and colors. If two or more identical tiles are next to each other (diagonally does not count), they disappear. To make this happen, the player can swap two adjacent tiles. However, there is a time limit to consider and empty places left behind by removed tiles are not usable. The goal is to clear the whole field.' FROM games WHERE igdb_id = 92682 ON CONFLICT (game_id, language_code) DO NOTHING;
