INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Honoo no Toukyuuji: Dodge Danpei', 'Honoo no Toukyuuji: Dodge Danpei is a Japanese manga series based on dodgeball, by Tetsuhiro Koshita, which was serialized in CoroCoro Comic. It was adapted into an anime from 1991 to 1992, and eight video game adaptations. A sequel, titled Honō no Tōkyūjo: Dodge Danko, began serialization on the Weekly CoroCoro Comic website on November 28, 2022. It has been nominated for the Next Manga Award in the web manga category in 2023.' FROM games WHERE igdb_id = 272812 ON CONFLICT (game_id, language_code) DO NOTHING;
