INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hagar the Horrible', 'Hägar The Horrible is a Jump''n''Run game based on the popular comics by Dik and Chris Browne. At the beginning of each levels, Hägar''s wife Helga gives him a list of items he has to collect in the current stage. Apart from fetching the items, the only goal is to reach the exit. Hägar is equipped with his normal shield and sword to fight enemies, but can also find more powerful extra weapons.' FROM games WHERE igdb_id = 47229 ON CONFLICT (game_id, language_code) DO NOTHING;
