INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('macross-ii', 39708, '1992-02-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa574.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5ldg.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Macross II', 'Super Spacefortress Macross is a vertically-scrolling shoot''em up based on the 1984 theatrical film in the Macross franchise, commonly known in English as Macross: Do You Remember Love?. Players control the VF-1 Valkyrie fighters of ace pilots Max Jenius and (in two-player games only) Hikaru Ichijyo in combat against the Zentradi. The game consists of seven levels, mostly based on action scenes from the film, including confrontations over Macross City, in the rings of Saturn, the surface of the devastated Earth, and the final battle against Boddole Zer. Gameplay is similar to Raiden: the Valkyrie can transform into one of three different modes by collecting the appropriate power-up: in Fighter mode, the ship fires a spread shot, Gerwalk mode has a narrow but powerful laser that passes through enemies, and Battroid mode features homing missiles. The intensity of the attacks can be upgraded in three stages through another power-up. There are also smart bombs to pick up that clear most enemies off the screen with one shot. Each level ends with a boss battle. Besides shooting down the hordes of enemies, picking up medals and rare Minmay dolls also increases the score. In two-player mode, both players take on the enemy simultaneously. Between levels, cutscenes recreate scenes from the film to illustrate the storyline.' FROM games WHERE igdb_id = 39708 ON CONFLICT (game_id, language_code) DO NOTHING;
