INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Camisole', 'Heroine Tenjin Shima is a manager of the lingerie shop, but on the behind this is a private investigation organization. One day a request is received from the National University to find the professor missing for a week already. All that''s known is that professor was interested in excavation of an ancient civilization and searched for a hidden treasure.' FROM games WHERE igdb_id = 128366 ON CONFLICT (game_id, language_code) DO NOTHING;
