INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('realms-of-arkania-blade-of-destiny', 8767, '1992-04-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2jkl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arvnc.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Realms of Arkania: Blade of Destiny', 'An epic RPG based on the popular German paper & pencil series, "Das Schwarze Auge" (The Dark Eye). Games that draw you in so deeply that the hours slip by like minutes. The atmospheric old-school feel, interesting game system and character development are fun, but the real strength of this games lies in their cool dungeons, which are chock full of tricks, traps, puzzles, and side events to keep you occupied for a long, long time. Fantasy... made fun. Thoughtful design and careful attention have produced a game that is just that... fun. A rich and detailed adventure to involve your mind, a true quest to challenge your imagination. Careful balancing and smooth game play make sure your time is spent playing. Realms of Arkania: Blade of Destiny is your answer to Fantasy Role-Playing. More of what you buy a computer game for... The proud Thorwalians of Arkania''s Northern Reaches face a dismal future. Rumors abound of a waiting army, banded together under one powerful Orc chieftain, standing ready to lay waste to Arkania''s towns and villages. All hope of survival rests on your ability to discover the whereabouts of a legendary artifact thought lost with its wielder in the midst of Orcish territory. Can this renowned sword, the Blade of Destiny, stop the siege?' FROM games WHERE igdb_id = 8767 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 8767 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
