INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Himitsu no Hanazono', 'Himitsu no Hanazono is essentially a visual novel. There are no verb commands and no real interaction with the environment. The choices are rather frequent and fairly numerous (usually four or five choices at most screens). Most of these choices, however, do not affect the plot, though they may alter subsequent dialogue. The player is also able to navigate the protagonist on school grounds and inside the main building in a top-down fashion, visiting locations in any order.' FROM games WHERE igdb_id = 123126 ON CONFLICT (game_id, language_code) DO NOTHING;
