INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tasac', 'In A.D. 20XX, humans are engaged in fierce warfare with TASAC - the alien bionic mutants. Landsy and Dagrel, commanders of Earth Defense Arms, are encountering the toughest enemies known to man. They must destroy TASAC to rescue the Earth, otherwise humans will be turned into slaves under the TASAC terrorism!' FROM games WHERE igdb_id = 48805 ON CONFLICT (game_id, language_code) DO NOTHING;
