INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('galactic-storm--1', 264082, '1992-03-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co70bo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sco7z3.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Galactic Storm', 'Galactic Storm is a chase-view shooter in the same vain as Galaxy Force or Taito''s own Night Striker. The player controls a spaceship equipped with a shield to withstand multiple hits, in addition to the standard shot there is a also a more effective special weapon in limited supply available. After taking off, the player flies on a predetermined course with some limited maneuvering room through the stages, facing of against waves of enemies (giant robots for example). At the end of a level, a stronger boss enemy awaits. Once this obstacle has been defeated, the ship''s shields get recovered to some extent and the player can continue the flight through various environments, including for example the wide-openness of space, planetscapes covered with trees, and narrow tunnels.' FROM games WHERE igdb_id = 264082 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 264082 AND ge.slug = 'shooter' ON CONFLICT DO NOTHING;
