INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('super-f1-circus-limited', 42265, '1992-10-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4cw2.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super F1 Circus Limited', 'Super F1 Circus Limited is largely identical to Cream''s earlier Super Famicom racing game Super F1 Circus, however it was shortly after the release of that game that Cream was given permission by FOCA (Formula One Constructors'' Union, an association of car manufacturers for Formula One) to use actual driver and team names for their subsequent Super F1 Circus games. Super F1 Circus Limited was quickly created to take advantage of this recent development. With the exception of the use of actual drivers/team names, there is no significant difference between this version of the game and the earlier Super F1 Circus. The series would see a proper sequel on the Super Nintendo, with enhanced graphics and additional features, with Super F1 Circus 2 in 1993.' FROM games WHERE igdb_id = 42265 ON CONFLICT (game_id, language_code) DO NOTHING;
