INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Troddlers', 'Troddlers is a puzzle game in the vein of Lemmings. The player takes control of an animal-like wizard who can create and remove blocks; these blocks are useful for both jumping onto and redirecting the path of the little Troddlers that you have to direct towards the exit. The tricky bit is that the Troddlers can climb walls and ceilings, following the edge of the world and the exit is often in the middle of the screen or with an obstacle in the way.' FROM games WHERE igdb_id = 39029 ON CONFLICT (game_id, language_code) DO NOTHING;
