INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Benkei Gaiden: Suna no Shou', 'Benkei Gaiden: Suna no Shou is a Japanese RPG set in a version of Ancient Japan filled with monsters and youkai. The game is a traditional top-down turn-based RPG in the vein of Dragon Quest. The player is able to choose between a male or a female avatar and name them, recruiting other characters as the game progresses.' FROM games WHERE igdb_id = 16140 ON CONFLICT (game_id, language_code) DO NOTHING;
