INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alice in Wonderland', 'Alice in Wonderland is a game based on Lewis Carrol''s classic story. The game is a side-scrolling adventure game in which the player controls Alice in her quest to return home from Wonderland. There''s over 40 different characters to speak with including important characters from the book such as the Mad Hatter, the Cheshire Cat and the Queen of Spade. Not all the characters are all too willing to help you getting home.' FROM games WHERE igdb_id = 175929 ON CONFLICT (game_id, language_code) DO NOTHING;
