INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BRap Boy', 'B. Rap Boys was produced by Kaneko in 1992. Kaneko released 33 different machines in our database under this trade name, starting in 1982. Other machines made by Kaneko during the time period B. Rap Boys was produced include Bakuretsu Breaker, Nexzr, Fujiyama Buster, Shogun Warriors, Gals Panic II, Berlin Wall, Magical Crystals, Air Buster, Gals Panic, and DJ Boy. Add by Lennux' FROM games WHERE igdb_id = 39880 ON CONFLICT (game_id, language_code) DO NOTHING;
