INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pop ''n Magic', 'A static screen action game in the style of Bubble Bobble or Don Doko Don, Pop ''n Magic allows you to trap enemies by firing your wand at them, then pick them up and throw them across the screen to destroy them. The bubbles they are trapped in are specific colours and care must be taken not to throw two of the same colour together as this will release the (now quite upset) creatures inside.' FROM games WHERE igdb_id = 37582 ON CONFLICT (game_id, language_code) DO NOTHING;
