INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ikasuze! Koi no Doki-doki Penguin Land MD', 'Ikazuse! Koi no Doki-doki Penguin Land MD — called just Doki-doki Penguin Land on Sega''s archive — is a Sega Mega Drive game released only in Japan as part of the Sega Game Toshokan service. It is an update to the previous games in the series, Doki Doki Penguin Land and Penguin Land, and features the same basic gameplay of having to guide an egg to the bottom of the screen.' FROM games WHERE igdb_id = 45731 ON CONFLICT (game_id, language_code) DO NOTHING;
