INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hyper Chou Pro Yakyuu ''92', 'Hyper Pro Yakyū ''92 follows the traditional rules of baseball. The player can choose to play as one of Japan''s professional baseball teams. Following that, the player has the option to play in the small or big baseball field. During the gameplay, the player will play the role of the batter to try and strike the ball thrown by the pitcher. If the ball is successfully hit, the player must control the batter to do a full run around the field square.' FROM games WHERE igdb_id = 46297 ON CONFLICT (game_id, language_code) DO NOTHING;
