INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shortline Railroad', 'Shortline is a real-time railroad management game that eschews complicated financial aspects (as in A-Train) and all realistic factors in favor of the pure joy of creating a miniature railroad. You goal is to assure an uninterrupted collision-free passage of different trains to target points, and your success both in traffic dispatch and railroad management and construction determines your score.' FROM games WHERE igdb_id = 223008 ON CONFLICT (game_id, language_code) DO NOTHING;
