INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Silent Dragon', 'In the 1990''s, a dark force appears on our planet. it''s the evil Dr. Bio, the twisted genius behind "Bio-Roid". By using advanced biotechnology, he creates mutant life forms with superhuman strength, terrorizing the human population. To stop the evil doctor, four men, each with courage and fortitude, are chosen to wage a just war against these creatures. And now, that battle has begun!' FROM games WHERE igdb_id = 39417 ON CONFLICT (game_id, language_code) DO NOTHING;
