INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Columbus: Ougon no Yoake', 'A nautical strategic RPG hybrid action in the vein of Uncharted Waters. You follow the life of Christopher Columbus as he goes from rookie captain to his landing in America. After a few tutorial missions, you get turned loose on an open world to build fame for yourself by doing quests, slaying rare monsters holed up in dungeon areas, etc., until a King of a prominent country can be convinced to support your expedition to the New World.' FROM games WHERE igdb_id = 48534 ON CONFLICT (game_id, language_code) DO NOTHING;
