INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'XPilot', 'XPilot is a multiplayer and open source game that runs on many platforms. Although its 2D graphics have improved over time, they still resemble the style of Thrust. Gameplay includes Capture the Flag, base defense, racing and deathmatches. XPilot uses a client–server architecture, in which a central metaserver receives information from all XPilot servers on the Internet.' FROM games WHERE igdb_id = 142943 ON CONFLICT (game_id, language_code) DO NOTHING;
