INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Day Dreamin'' Davey', 'The game starts out with the main protagonist, Davey, arriving at school. Then a bully (Lumpy) takes his pencil. Now all throughout class Davey is daydreaming of being in several different locations revolving around Medieval Times, the Wild West and Ancient Greece and each level contains at the end something Davey must collect that will always resemble the shapes of school items (e.g., a pencil, a ruler or a trophy).' FROM games WHERE igdb_id = 48139 ON CONFLICT (game_id, language_code) DO NOTHING;
