INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SegaSonic the Hedgehog', 'SegaSonic the Hedgehog is a 1992 LCD game which was used as a promotional item in Japan. They were found in UFO catchers. Three versions were created which only vary by the color and by what is drawn on the case. There was also a handy keychain attached to the case.' FROM games WHERE igdb_id = 198602 ON CONFLICT (game_id, language_code) DO NOTHING;
