INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Phantom Air Mission', 'Scramble into the cockpit of the only combat jet fighter game on Game Boy! The Navy F-14 Tomcat, a hero of the Persian Gulf War, soars to new heights in this first-person aerial assault simulator. * Fully instrumented control panels! * HUD for enemy targeting; radar and landing displays for smooth navigation! * Complete 360 rotation! * Wing-mounted 50mm cannons; AIM-54 air-to-air missiles; ECM system to confuse oncoming warheads! * Dynamic aircraft carrier takeoff and landing; in-flight refueling!' FROM games WHERE igdb_id = 49041 ON CONFLICT (game_id, language_code) DO NOTHING;
