INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Animal Quest', 'Animal Quest is an educational game for all ages where you play as an animal. The game is played on a grid field, on which other animals, hunters, and other obstacles are randomly placed. The player''s goal is to catch its prey (other animals or plants) while avoiding not getting eaten or killed. Each animal has its own difficulty level; a prey animal has a harder time than a lion. The game features detailed information about the animals.' FROM games WHERE igdb_id = 70175 ON CONFLICT (game_id, language_code) DO NOTHING;
