INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Inspecteur Banaan en de ontvoering van Mabella', 'A Dutch Point ''n click adventure created by Torpedo Software for Davilex. You play a cop named Govert Banaan and you have to investigate a kidnapping case of the fictional pop star MaBella. In the game you have will explore Amsterdam. The graphics style is a mix of real-life photographs and cartoon characters.' FROM games WHERE igdb_id = 144462 ON CONFLICT (game_id, language_code) DO NOTHING;
