INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'New Atomic Punk: Global Quest', 'New Atomic Punk: Global Quest is a 1992 video game released by Irem under license from Hudson Soft for arcades. It is part of the Bomberman series. It was the second Bomberman game to be released for arcades, preceded by Bomberman (1991), which was also released by Irem.' FROM games WHERE igdb_id = 39495 ON CONFLICT (game_id, language_code) DO NOTHING;
