INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Plan 9 From Outer Space', 'Plan 9 from Outer Space is a point and click adventure game developed by Gremlin Ireland for the Amiga and Atari ST. It was released in 1992 and published by Gremlin Graphics and Konami. A DOS version was made but only released in the USA and Europe. There were two editions of the game. The rarest one came solely packed with the Plan 9 game, while the other edition came with a VHS copy of the film.' FROM games WHERE igdb_id = 12717 ON CONFLICT (game_id, language_code) DO NOTHING;
