INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('konami-hyper-soccer', 48284, '1992-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6o1s.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Konami Hyper Soccer', 'There is a lot more to this soccer game than meets the eye... Compete in a tournament, play against the computer or your friend, or even watch the computer play both teams. In the event of a tie, you get to do a real penalty kick play-off. You can choose your team from among 24 different countries, and give the team the qualities you like. Figure out your strategy before the game and set your formation. Winning depends on your skill... and a little bit of luck!' FROM games WHERE igdb_id = 48284 ON CONFLICT (game_id, language_code) DO NOTHING;
