INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pantheon', 'Pantheon is 2 genres in 1: A vertical shoot''em up and an arcade adventure game (the latter being the main game). In the arcade adventure game you are Sergeant Silver first in ancient Greece and later in outer space. To complete the main game you have to solve puzzles (and bring certain items to temples) and fight enemies' FROM games WHERE igdb_id = 128470 ON CONFLICT (game_id, language_code) DO NOTHING;
