INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jack Nicklaus Golf & Course Design: Signature Edition', 'Jack Nicklaus Golf & Course Design: Signature Edition is a 1992 golf video game developed by Sculptured Software and published by Accolade for MS-DOS. It is part of a series of games named after golfer Jack Nicklaus, and follows Jack Nicklaus'' Unlimited Golf & Course Design (1990). Like its predecessor, the game includes a golf course designer that allows the player to create customized courses.' FROM games WHERE igdb_id = 69639 ON CONFLICT (game_id, language_code) DO NOTHING;
