INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ninja Burai Densetsu', 'Ninja Burai Densetsu is a 1991 strategy game by Sega for the Sega Mega Drive released exclusively in Japan. The game plays similarly to other strategy games such as SystemSoft''s Daisenryaku games and Sega''s own Shining games. You are in control of a team of ninjas fighting another team. C selects a ninja/confirms an action. B cancels an action, or if no action is in progress, selects the next ninja. A opens the battle menu, which allows you to end your turn. Battles are fully automatic. Unique to Ninja Burai Densetsu are side-scrolling special stages: should you move a ninja onto a special space, they will go into a town where they can get various helpful items from townsfolk.' FROM games WHERE igdb_id = 46072 ON CONFLICT (game_id, language_code) DO NOTHING;
