INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sword of Honour', 'You are a noble ninja, who has to prove the honour of shogun Yuichiro by recovering a stolen sword from the evil Toranaga. Walking from a village to a castle, you fight enemies and avoid traps using your skills in martial arts and Japanese weapons, collecting useful items and uncovering the twisty plot of the story.' FROM games WHERE igdb_id = 12790 ON CONFLICT (game_id, language_code) DO NOTHING;
