INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crüe Ball', 'Crüe Ball is a 1992 pinball video game. It is themed to glam metal band Mötley Crüe, it features three of their songs: "Dr. Feelgood," "Live Wire," and "Home Sweet Home." It features nine levels which are partitioned into three sections: a bottom, middle and top area. Players must smash a wall behind a floating head named Craig which will in turn "crank it up" which leads the player into the next level. The final boss of the game is the evil Mr. Gore, who can only be defeated by shooting three balls into his mouth.' FROM games WHERE igdb_id = 46282 ON CONFLICT (game_id, language_code) DO NOTHING;
