INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Text Tiles', 'Text Tiles is a fast-paced word spelling strategy game. Use the given letters to spell words horizontally or vertically. The longer the words, the more points you get. Spell two or more words at the same time for an extra bonus! The clock is always ticking, so use your time wisely. If you don’t place a letter quick enough it will turn into a block. Then you’ll have to work around it!' FROM games WHERE igdb_id = 46564 ON CONFLICT (game_id, language_code) DO NOTHING;
