INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NFL Football', 'NFL Football is an American football video game for the Atari Lynx. It was developed by Blue Sky Software, and published by Epyx in 1992. The Lynx system is to be rotated for vertical orientation in the player''s hands, with the display zooming in and out from an overhead perspective. For two-player mode, a computer opponent is available or two Lynx systems can be connected via a cable. The players can choose a team from either the AFC or the NFC. The game offers an extensive clipboard of plays and formations "designed by a real NFL coordinator".' FROM games WHERE igdb_id = 175899 ON CONFLICT (game_id, language_code) DO NOTHING;
