INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Goal! Two', 'Get ready for the ultimate rematch! It''s too real! Too fast! Too good to be anything less than the best soccer game ever created for the NES! It''s GOAL! TWO, the long-awaited sequel to the original title that set the standard for world class soccer simulation. It''s living proof that you can never get too much of a great thing!' FROM games WHERE igdb_id = 48162 ON CONFLICT (game_id, language_code) DO NOTHING;
