INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pensate', 'Pensate is a single-player, shareware, strategy/puzzle, turn based game that is based on the 1983 game by Penguin Software. This implementation is played on an 8x8 board and has ten levels. The players objective is to navigate their piece from the bottom of the board to the top, their token can only be moved horizontally or vertically. Also on the game area are opposing pieces which behave like chess pieces which move position every time the player makes a move, so the migration from the bottom of the screen to the top is complicated by the need to avoid being captured by these pieces.' FROM games WHERE igdb_id = 117025 ON CONFLICT (game_id, language_code) DO NOTHING;
