INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tetris Classic', 'Geometric shapes fall from the top of a playfield to rest on the bottom; fit the pieces together, and the line they form disappears. If the pieces don''t form lines and eventually stack up to the top of the playfield, the game is over. Difficulty increases by dropping the pieces faster and faster over time.' FROM games WHERE igdb_id = 79545 ON CONFLICT (game_id, language_code) DO NOTHING;
