INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mad Dog II: The Lost Gold', 'The sequel to American Laser Game''s original Mad Dog McCree, with pretty much the same gameplay and motion capture graphics. This PC conversion seems to have been tweaked a bit to be more stable than the original Mad Dog. There''s also somewhat limited replay value as you can choose from 3 different guides for 3 different routes through the game.' FROM games WHERE igdb_id = 4269 ON CONFLICT (game_id, language_code) DO NOTHING;
