INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crossfire: The Multiplayer Adventure Game', 'Crossfire is an open source, cooperative multiplayer graphical RPG and adventure game. Since its initial release, Crossfire has grown to encompass over 150 monsters, about 3000 maps to explore, an elaborate magic system, 13 races, 15 character classes, a system of skills, and many artifacts and treasures. Crossfire is based in a medieval fantasy world and is similar to other games of this genre.' FROM games WHERE igdb_id = 171544 ON CONFLICT (game_id, language_code) DO NOTHING;
