INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fixeight', 'Fixeight is a run-and-gun arcade game made by Toaplan in 1992. It is the Spiritual Sequel to "Out Zone."  The plot is rather simple: Your character is sent to the alien planet Fortune to destroy it, and with it the Gozzu invasion of our universe.  As a follow-up to Out Zone, Fixeight fixes many of the problems that its predecessor had. The main gimmick of the game are the eight unique characters, each of which have different weapons in their arsenal.' FROM games WHERE igdb_id = 46835 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 46835 AND ge.slug = 'shooter' ON CONFLICT DO NOTHING;
