INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Loader Larry', 'Larry Lontrose is a part-time dock loader. He is very ambitious and wants to be promoted up the corporate ladder. By solving the 40 mind-bending puzzle rooms, you can help Larry fulfill his dreams. Each room has objects like boxes, balloons, TNT and much more! Use these objects and avoid others, to reach the door in each room to complete a level.' FROM games WHERE igdb_id = 73809 ON CONFLICT (game_id, language_code) DO NOTHING;
