INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rome: AD 92', 'Rome: Pathway to Power (released as Rome: AD 92 in Europe) is an adventure game with strategic elements set in ancient Rome. Your name is Ettore and you start as a Roman slave. In this adventure player will have to advance, by any means possible, through the ranks of Roman society. The journey to Rome will lead you to become a Roman citizen, then a Caesar''s trusted lieutenant, a military general in Britannia end in Egypt, a roman consul and eventually become Caesar himself' FROM games WHERE igdb_id = 2525 ON CONFLICT (game_id, language_code) DO NOTHING;
