INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kye', 'Kye is a real-time puzzle game with a variety of interacting objects. It takes ideas from puzzle games like Sokoban and Boulder Dash, but the inclusion of active objects gives it a real-time component, and it can also produce arcade-game levels like those found in Pac-Man. Anyone can create new levels for the game.' FROM games WHERE igdb_id = 98948 ON CONFLICT (game_id, language_code) DO NOTHING;
