INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gluk the Thunder Warrior', 'The ARCA DORADA, the most valuable relic of the people of Tibet, has been stolen during the celebration of the new year. This relic contains the spirit of strength - The population is in the hands of the ruthless thieves. GLUK must retrieve the relic. The sacred monks of Tibet have given the power of thunder to help him succeed in his mission. There is no time to lose. The adventure begins. GOOD LUCK!' FROM games WHERE igdb_id = 48565 ON CONFLICT (game_id, language_code) DO NOTHING;
