INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Devilish: The Next Possession', '"Devilish" is different from other paddle games by letting you play with two paddles. The lower one behaves just like a usual paddle - you use it to prevent the ball from dropping down. The upper one can move and turn, allowing you to hit the ball from different angles and from different parts of the screen. You advance through levels by destroying bricks and enemies, going up until the level boss enemy appears.' FROM games WHERE igdb_id = 46222 ON CONFLICT (game_id, language_code) DO NOTHING;
