INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Big Bang Show', 'Big Bang Show is an exciting and challenging game of skills featuring Albertus the mad scientist and his latest discovery, Sparkie, a bouncing ball of energy.  Only when the player collects the right items, avoids the traps and answers Albertus'' questions, can he hyper-space jump into another period. This requires reflexes, speed, knowledge and memory.  More than just a game, the host Albertus adds warmth, humour and personality, presenting realistic adventure for the participants to experience.  Big Bang Show offers a rich graphic environment, including computer graphics for all game screens, digitalized images to illustrate the five periods, video sequences for Albertus'' appearances, a sound element for the sound of the ball in movement or in collision with objects, and an original musical accompaniments to the game.' FROM games WHERE igdb_id = 45943 ON CONFLICT (game_id, language_code) DO NOTHING;
