INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Legends of the Diamond', 'Each player uses his career stats to determine how well he plays on the baseball field. Fielders have to be controlled manually and baseballs can be manipulated mid-flight like in an arcade game.' FROM games WHERE igdb_id = 48253 ON CONFLICT (game_id, language_code) DO NOTHING;
