INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('3rd-degree', 45948, '1992-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/p354zcneemwbgnnllfow.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '3rd Degree', 'Would you like to protect your boss who is having an affair? If you got an anniversary gift you didn''t like, what would you do? If you found $1 million, would you keep it? You know how you would answer--but what about your friends? Do you think you know? You''ll be quizzed on love, family, career, money and potpourri. Sometimes you''re right, and sometimes you''re not! The answers will surprise you. It''s 3rd Degree--the first CD-i game show. You are the contestant in the hot seat in this interactive game. Meet hilarious hosts and a very astute judge. Choose from an assortment of colorful characters and challenge your friends to three rounds of provocative dilemmas! In 3rd Degree it all adds up to lots of laughs, and the kind of lively conflict everyone loves.' FROM games WHERE igdb_id = 45948 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 45948 AND ge.slug = 'strategy' ON CONFLICT DO NOTHING;
