INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'David Crane''s Amazing Tennis', 'A tennis game featuring both an exhibition and a tournament mode. In the head to head exhibition mode, the player can choose their opponent (with the higher ranked opponents being better than the lower ranked ones). The tournament mode allows for 16 different players to compete to become the champion. Both of these modes can be played on either grass, hard, or a clay court. The player can also choose whether to be either a left or right handed tennis player.' FROM games WHERE igdb_id = 46534 ON CONFLICT (game_id, language_code) DO NOTHING;
