INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gomenne Angel: Yokohama Monogatari', 'One day the hero picks up a notebook and it turns out to be a possession of a girl student of St. Francis girls academy where his fiance is teaching. All three of them meet in a cafe, but girl looks very anxious. Her sister disappeared. And we''ll help to find her.' FROM games WHERE igdb_id = 271463 ON CONFLICT (game_id, language_code) DO NOTHING;
