INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Mario Bros. & Friends: When I Grow Up', 'Super Mario Bros. & Friends: When I Grow Up is an MS-DOS computer game featuring Mario and friends. The game is essentially a digital coloring book, containing illustrations by Rick Incrocci. A few pages have animated sequences. The pages are themed after common careers. Characters in the game include Mario, Luigi, Princess Toadstool, Toads, and Bowser. Super Mario Bros. & Friends: When I Grow Up features Bowser both as he appears in video games and as he does in the Super Mario cartoons. Link also makes cameo appearances on the Chef/Waiter and Travel guide pages.' FROM games WHERE igdb_id = 131951 ON CONFLICT (game_id, language_code) DO NOTHING;
