INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mega Man 3: The Robots are Revolting', 'Mega Man 3: The Robots are Revolting is a game in the original Mega Man series licensed by Capcom USA and developed and published by Hi-Tech Expressions in association with Rozner Labs In 1992 for DOS. It is a sequel to the first Mega Man for DOS, with no Mega Man 2 for DOS in between.' FROM games WHERE igdb_id = 88384 ON CONFLICT (game_id, language_code) DO NOTHING;
