INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('town-and-country-surf-designs-ii-thrillas-surfari', 48177, '1992-04-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6oxk.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Town & Country Surf Designs II: Thrilla''s Surfari', 'Whoa, Thrilla Gorilla! Bag your boards and lay back tall for the raddest, weirdest surf and skate action ever! Wazula, an evil Kahuna, has stolen your babe and taken her to Africa. No curbs and quarter-pipes here, just the ultimate skate challenge of gnarly jungles and bakin'' deserts! It''s hardcore surfin'' down killer volcanoes and mammoth waterfalls... ever catch a wave riding a shark? Wazula''s got some smooth moves of his own, like a two-headed flying Rhino, a saw-toothed Great White, and a way-tough Lava Monster big as a volcano. So get rippin'' through the scorpions, slashin'' through the rapids, and trash that Wazula doofus! But don''t choke, Thrilla... or your babe''s toast.' FROM games WHERE igdb_id = 48177 ON CONFLICT (game_id, language_code) DO NOTHING;
