INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dial Q wo Mawase!', 'Dial Q wo Mawase!, alternatively called Dial Q o Mawase! and often pirated under the name Kyuukyoku Mahjong or Mahjong Lady, is a pornographic mahjong game for the Sega Mega Drive originating in Japan, but developed by unknown developers in some unknown year. The game is somewhat often pirated by other Japanese and Chinese pirates. It appears to be hacked out of Mahjong Cop Ryuu and steals the Cube/Noriyuki Iwadare sound driver.' FROM games WHERE igdb_id = 45617 ON CONFLICT (game_id, language_code) DO NOTHING;
