INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chibi Maruko-chan: Waku-waku Shopping', 'Chibi Maruko-chan: Waku-waku Shopping is the 8th video board game based on Momoko Sakura''s Chibi Maruko-chan slice of life manga and anime about a troublemaking grade-schooler and her friends and family. Maruko and her classmates Tamae, Kazuhiko, and Sueo move around a board and increase/decrease their money and happiness totals depending on where they land. Other squares might produce random effects or offer items to buy.' FROM games WHERE igdb_id = 45644 ON CONFLICT (game_id, language_code) DO NOTHING;
