INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wally Bear and the NO! Gang', 'Wally Bear and the NO! Gang is a side-scrolling platformer designed to teach kids the dangers of doing drugs, gang banging and hanging out with the wrong crowd. Most obstacles can be avoided, but Wally can also bop enemies on the head with his skateboard. The game features seven levels to traverse and a total of two power ups to find all while racing against the clock to help out your friends.' FROM games WHERE igdb_id = 48260 ON CONFLICT (game_id, language_code) DO NOTHING;
