INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The King of Rally', 'The King of Rally, or The King of Rally: Paris - Moscow - Beijing, is a cross-continental rally racing game for the Super Famicom. The perspective is at a slight overhead angle, making full use of the Super Nintendo''s Mode 7.' FROM games WHERE igdb_id = 38111 ON CONFLICT (game_id, language_code) DO NOTHING;
