INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Quarky & Quaysoo''s Turbo Science', 'LOOK OUT! You''re surrounded by science!! It''s in your skateboard. It''s in your lunch. It''s in that gooey stuff that collects on your Nintari powerpad... And it''s in this box!! Learn why planes fly, lightbulbs glow, magnets attract, and wrecking balls bash as you compete in a laser-fast science race with Quarky & Quaysoo. Along the way, you''ll discover facts about chemistry, machines, thermal energy, and more of that important science stuff that''s EVERYWHERE!' FROM games WHERE igdb_id = 46981 ON CONFLICT (game_id, language_code) DO NOTHING;
