INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heracles no Eikou: Ugokidashita Kamigami', 'Heracles no Eikou: Ugokidashita Kamigami is a spin-off entry in the Glory of Heracles series for the Gameboy and is a direct continuation of the first game. The title was developed by SAS Sakata and published in Japan on December 27, 1992 by Data East. An English fan translation was released by HTI in 2012 under the title "The Glory of Heracles: Snap Story."' FROM games WHERE igdb_id = 129545 ON CONFLICT (game_id, language_code) DO NOTHING;
