INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gimme-a-break-shijou-saikyou-no-quiz-ou-ketteisen-2', 267652, '1992-08-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co741y.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gimme a Break: Shijou Saikyou no Quiz-ou Ketteisen 2', 'Gimme A Break: Shijou Saikyou no Quiz Ou Ketteisen 2, released for the Famicom in 1992, is the second game in a series by Yonezawa PR21 based on a real Japanese game show. This game is significantly better than the first game in the series, but also much harder. If you can''t read Japanese very fast and if you are not going to cheat using save states, then this game is going to be a huge problem to beat. But it seems like a native Japanese speaking person would find this game to be a lot of fun. The game flow is the following. You choose a region of Japan that your character lives in. Then you will compete in the regional quiz championships. This is composed of a qualifying quiz that you have to get 10 questions right to pass, then you compete against the other contestants from your region that also passed the qualifying test. If you get first or second place, you will move on to the national level of the game. Again, you must pass a qualifying quiz. Then you will compete against the other contestants that made it this far. Finally, the winner will compete against the Quiz King.' FROM games WHERE igdb_id = 267652 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 267652 AND ge.slug = 'quiz-trivia' ON CONFLICT DO NOTHING;
