INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('shura-no-mon', 46258, '1992-09-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/dm7jew5fzpdhfzfrhy5b.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shura no Mon', 'Legends tell of an invincible martial art known as Mutsu Enmei-Ryu, an unarmed style that allows the user to defeat any number of armed opponents using incredible speed and strength. This is the story of three generations of those who bear the name Mutsu, and their encounters and battles with the strongest fighters of their era. The story is about Mutsu Tsukumo, a young and normal looking youth who challenges great foes to prove that his style of fighting is the best in the world. His Ryuha, or fighting style is called Mutsu Enmei Ryu. A style that is said to have never lost in its 1000 year history. Tsukumo not yet a perfect fighter also increases his strength as the story progresses.' FROM games WHERE igdb_id = 46258 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 46258 AND ge.slug = 'fighting' ON CONFLICT DO NOTHING;
