INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Daisy Quest and Daisy''s Castle', 'Daisy Quest is an educational game intended for young children. The goal is to find the titular dragon Daisy in a magical game of hide-and-seek. While you explore the world, you come across various simple mini-games intended to test your knowledge of vowel and consonant sounds. When each mini-game is completed, a treasure will be collected which reveals part of Daisy''s hiding spot. After all of the treasures have been collected, the player wins the game by finding Daisy at the revealed location.' FROM games WHERE igdb_id = 285760 ON CONFLICT (game_id, language_code) DO NOTHING;
