INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'OutRunners', 'Outrunners is a driving game that allows you to gon a world tour of various stages. Follow the selected drive course by choosing one out of the 8 different type cars whose characteristics such as perspectives, power, transmission, steering wheel manoeuvrability, etc. are different. Appealing to young chouples who drive in a stylish manner, players who skillfully make turns at the corners, and so on, amid the beautiful sceneries throughout the world, this game is sure to enhance the activation of the locations.' FROM games WHERE igdb_id = 39574 ON CONFLICT (game_id, language_code) DO NOTHING;
