INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beasts of Horror', 'One of the first Israeli action games! Beasts of Horror you play as a warrior from millions of years in the past. Your people have recently left the caves and started a village. However, your wife returned to the caves to gather the rest of her belongings and has not returned. Now you must take up arms against fire-breathing dragons, deadly wasps, and other strange creatures to rescue your wife. Once thought lost, this game was eventually rediscovered by the Israeli Game Conservation Movement.' FROM games WHERE igdb_id = 265940 ON CONFLICT (game_id, language_code) DO NOTHING;
