INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Leather Goddesses of Phobos 2: Gas Pump Girls Meet the Pulsating Inconvenience from Planet X!', 'Leather Goddesses of Phobos! 2: Gas Pump Girls Meet the Pulsating Inconvenience from Planet X is a graphic adventure game written by Steve Meretzky and published by Activision in 1992 under the Infocom label. As 1 of 3 different player characters (male, female or alien!) you unravel puzzles to thwart the Pulsating Inconvenience from Planet X to save Earth in the year 1956!' FROM games WHERE igdb_id = 14558 ON CONFLICT (game_id, language_code) DO NOTHING;
