INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('spaceward-ho', 47296, '1992-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8fr8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar30rp.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spaceward Ho!', 'Spaceward Ho! is a turn-based science fiction computer strategy game that was written by Peter Commons, designed by Joe Williams (Joedelta) and published by Delta Tao Software. The first version was released in 1990, and further upgrades followed regularly; the current version, 5.0.5, was released on July 8, 2003. It has received wide recognition in the Macintosh community, for example being inducted into the Macworld Game Hall of Fame. Spaceward Ho! can be categorized in the 4X game genre (eXplore, eXpand, eXploit, eXterminate) with a theme of galactic conquest. It took many elements of its design from the earlier Reach for the Stars, but expanded on many of that game''s basic themes while taking advantage of the larger memory and better graphics available on the Mac platform.' FROM games WHERE igdb_id = 47296 ON CONFLICT (game_id, language_code) DO NOTHING;
