INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-carl-lewis-challenge', 12532, '1992-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/b5oblqqfprted0reezf3.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Carl Lewis Challenge', 'Your knee rests on the hard surface of the track. Fingers splayed, you adjust your foot slightly on its starting block. A bead of sweat squeezes from your brow as you focus on the race ahead. Weeks of intensive training have culminated in your anticipation of the starter''s gun, poised to put everything you''ve got into the next few seconds. 100 meters suddenly seems a very long way... Take the Carl Lewis Challenge and select, manage, train and control a team of athletes in their all-out attempts to win gold in Javelin, 100m Sprint, 110m Hurdles, High Jump or Long Jump. Follow in Carl Lewis'' footsteps and go for gold!' FROM games WHERE igdb_id = 12532 ON CONFLICT (game_id, language_code) DO NOTHING;
