INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kyuukyoku Harikiri Koushien', 'Kyuukyoku Harikiri Koushien is a baseball game for the Famicom, not unlike any of the others. The main drawing point with this one is that there are close to 100 teams you can choose from. Plus, the traditional baseball stats are not used; rather each player has a set rating for strength and speed, and that is all you get to go by. A neat addition is the power meter, which can help your team get ahead if used properly.' FROM games WHERE igdb_id = 315336 ON CONFLICT (game_id, language_code) DO NOTHING;
