INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tsurupika Hagemaru: Mezase! Tsuruseko no Akashi', 'Tsurupika Hagemaru: Mezase! Tsuruseko no Akashi is 2D platforming game released for the Famicom (NES) in 1991. The game is based on a Japanese children''s manga and 58-episode anime series called Tsurupika Hagemaru (Little Baldy Hagemaru), and features many of its characters including protagonist Hagemaru whom the player controls.' FROM games WHERE igdb_id = 48874 ON CONFLICT (game_id, language_code) DO NOTHING;
