INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('av-poker-world-gambler', 42089, '1992-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6xcf.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'AV Poker: World Gambler', 'Unlicensed PC Engine release by Games Express. AV Poker is not a full poker simulator, but a simple gambling game. You choose from Normal, which is a standard game or Special Mode, where you travel around the world to show off your gambling skills. The poker part of the game is extremely simple. You place a bet, get a hand dealt to you, choose which cards to hold, and get a second deal to fill in the discards. If you match any of the standard poker hands, you win. You then get the options of taking the cash or playing a higher-lower game to increase your winnings significantly. Occasionally, you also get a fruit machine style mini-game which gives you the chance of winning ''special'' cards that can be used during the game.' FROM games WHERE igdb_id = 42089 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 42089 AND p.igdb_id = 86 ON CONFLICT DO NOTHING;
INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-irem-skins-game', 44452, '1992-11-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5z1n.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Irem Skins Game', 'A golf game featuring four different game modes. The four game modes are Skins game, Match play, Stroke play, and Tournament. The Skins game has players compete for prize money on each individual hole. Match play involves 2 golfers competing to see who can win the most holes out of 9 or 18 holes. Stroke play counts the total number of strokes over a course of a golf game. The golfer with the least amount of strokes wins. Tournament mode has golfers competing in either one day (18 holes) or two days (36 holes) of golf. Scoring is figured out by how many strokes over or under par a golfer made to finish a hole. Gameplay consists of first choosing a golfer type of either a power hitter, all-around, technician, or magician. Each type has its own proficiencies in the drive, power, accuracy, hook, slice, and back spin categories. When on the golf course the player can choose a club, their stance, direction of where to hit the ball, and the power of the swing. Once that is decided, the swing is determined by a meter which measures the accuracy of the shot and determines whether the ball gets hit straight, hooks, or slices.' FROM games WHERE igdb_id = 44452 ON CONFLICT (game_id, language_code) DO NOTHING;
