INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Track & Field in Barcelona', 'Track & Field in Barcelona released on the NES was a re-release in Europe in 1992 in the light of the 1992 Summer Olympics, earlier versions were simply known as Track & Field. The opening song for the NES version is the Chariots of Fire theme by Vangelis (which was also used in the arcade version''s high score screen). In the original arcade game, the player uses two "run" buttons (or a trackball in later units that replaced buttons damaged from overuse) and one "action" button to control an athlete competing in the following six events:' FROM games WHERE igdb_id = 48893 ON CONFLICT (game_id, language_code) DO NOTHING;
