INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shadow of the Beast III', 'Shadow of the Beast III is a platform game developed by Reflections and published by Psygnosis in 1992, exclusively for the Amiga. It is the sequel to Shadow of the Beast and Shadow of the Beast II. The gameplay combines action and puzzle solving, with an emphasis on the latter. Typical puzzles involve levers and chains moving hooks, bridges, and doors.' FROM games WHERE igdb_id = 12221 ON CONFLICT (game_id, language_code) DO NOTHING;
