INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stunt Buggies', 'Stunt Buggies, a maze driving game similar to Rally-X, was developed and published by Codemasters for the Commodore 64 in 1992. This game involves 1 or 2 players piloting buggies around dangerous mazes filled with renegade buggies on a quest to collect all the bombs in order to escape the maze. Released originally in the Quattro Arcade computation, The NES versions were released as multicarts and were published by Camerica without a license by Nintendo.' FROM games WHERE igdb_id = 164759 ON CONFLICT (game_id, language_code) DO NOTHING;
