INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doukyuu-sei', 'Doukyuu-sei is a 1992 erotic dating sim (the first of its kind) where the player can meet 14 girls to have a romantic relationship with. The player takes the role of a high-school student (default name Takurou) in a Japanese town; his parents have just moved into a large mansion in a good district. The boy has to go to the new school, but his mind is preoccupied with one subject only: pretty girls. Instead of studying hard, Takurou decides to explore the city and to find out more about its female inhabitants.' FROM games WHERE igdb_id = 59997 ON CONFLICT (game_id, language_code) DO NOTHING;
