INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Diet Go Go', 'Diet Go Go was produced by Data East in 1992.  Data East released 149 different machines in our database under this trade name, starting in 1980.  Other machines made by Data East during the time period Diet Go Go was produced include Mutant Fighter, Boogie Wings, Aaron Spelling, Hook Pinball, Lethal Weapon 3, Death Brade, Checkpoint, Wolf Fang, Joel Silver, The Pinball, and Joe & Mac - Ikusae Genshizin.' FROM games WHERE igdb_id = 39872 ON CONFLICT (game_id, language_code) DO NOTHING;
