INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Carriers at War', 'Naval wargame, a remake of the 1984 Carriers at War. It is based on World War II naval warfare and focuses on the Pacific Theater. Exactly like the original game, this remake contains 6 scenarios based on the Attack on Pearl Harbor, the Battle of the Coral Sea, the Battle of Midway, the Battle of the Eastern Solomons, the Battle of the Santa Cruz Islands, and the Battle of the Philippine Sea.' FROM games WHERE igdb_id = 281002 ON CONFLICT (game_id, language_code) DO NOTHING;
