INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars: Attack on the Death Star', 'Star Wars: Attack on the Death Star recreates the climactic Death Star trench run from the original film in 3D wireframe graphics. Players pilot an X-Wing fighter through space combat with TIE Fighters, navigate the Death Star''s surface defenses, and attempt to destroy the station by launching torpedoes into its thermal exhaust port. The game features digitized voice acting and represents an early attempt to bring the iconic movie sequence to life in an interactive format.' FROM games WHERE igdb_id = 45379 ON CONFLICT (game_id, language_code) DO NOTHING;
