INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'John Madden Football ''93: Championship Edition', 'Now you can determine the greatest team of all time! FEATURING • 38 Championship teams plus 2 All Madden teams. • John''s digitized commentary. • Tougher computer opponents; smarter offense, more aggressive defenses. • Battery back-up; no passwords needed. • Team and player stats saved throughout the playoffs. • QB Stop Clock play. • No huddle offense. • Split screen play calling.' FROM games WHERE igdb_id = 4482 ON CONFLICT (game_id, language_code) DO NOTHING;
