INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Thunder Hoop', 'Thunder Hoop is a 2D side-scrolling platform game that puts players in the shoes of Thunder Hoop. Thunder Hoop has to stop the uncontrollable creatures professor Genbreak has released into to the world. Genbreak was forbidden to continue his dangerous research in creating these creatures, but exasperated, he created them all the same. Thunder Hoop was specifically developed in a laboratory to counter these creatures.' FROM games WHERE igdb_id = 40213 ON CONFLICT (game_id, language_code) DO NOTHING;
