INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SD Kidou Senshi Gundam: V Sakusen Shidou', 'SD Kidou Senshi Gundam: V Sakusen Shidou is a 2D side-scrolling shooter/brawler featuring characters from the Gundam universe. Specifically, it draws from the SD (Super Deformed) Gundam continuity in which all the Gundam mech suits are sentient robotic creatures. The player must pass through various waves of enemies, either on the ground or in flight, in order to proceed to the end of the stage, where occasionally a boss must be fought.' FROM games WHERE igdb_id = 38160 ON CONFLICT (game_id, language_code) DO NOTHING;
