INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cosmos Cop', 'Cosmos Cop is a pseudo-3D into-the-screen shoot ''em up that is similar to Sega''s Space Harrier. However, the game experiences a lot of image breakup on the screen due to the NES''s limited capability of handling first-person scaling.[2]' FROM games WHERE igdb_id = 48314 ON CONFLICT (game_id, language_code) DO NOTHING;
