INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('shining-force-gaiden-ensei-jashin-no-kuni-he', 46307, '1992-12-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co49lf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scesm7.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shining Force Gaiden: Ensei - Jashin no Kuni he', 'Shining Force Gaiden is a turn-based tactical RPG. Battles take place in square grids, and each unit occupies 1 square. Units can belong to one of two sides: allies (controlled by the player) or enemies (controlled by the computer AI). Each unit can move up to a fixed amount of squares along the battlefield, determined by its Move statistic. Depending on its location relative to enemies and to allies, a unit also has the option to attack, cast a spell, use an item, search (if adjacent to a treasure chest), or stay and do nothing, all of which end the unit''s turn. Some commands, such as equipping or dropping items, don''t count as actions, and the character''s turn is able to continue. The order of the turns is determined by the unit''s agility score and a random seed. Units can use offensive actions, such as physical attacks or offensive magic, only on units belonging to the other side and can use supportive actions, such as healing magic, stat-enhancing magic, and items, only on units belonging to the same side. This game (together with Shining Force: The Sword of Hajya) was later given a remake named Shining Force CD, released on the Sega CD. This remake also saw a western release to both North America and Europe and the full english title was "Shining Force Gaiden: Towards the Root of Evil". In 2013 the Game Gear original game got ported to the Nintendo 3DS Virtual Console (Japan only).' FROM games WHERE igdb_id = 46307 ON CONFLICT (game_id, language_code) DO NOTHING;
