INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pizza Pop!', 'The Pizza Boy must deliver pizzas to various dangerous locations in order to make enough money to buy his girlfriend an engagement ring. He is thwarted by many enemies, including his romantic rival who appears frequently to take him down. Points are scored at the end of each stage based on completing stages quickly, defeating enemies and recovering extra pizzas.' FROM games WHERE igdb_id = 48378 ON CONFLICT (game_id, language_code) DO NOTHING;
