INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Popeye 3: WrestleCrazy', 'Popeye 3 is a 1 or 2 player wrestling game shown from the side with the screen showing the whole of the ring. The joystick moves Popeye about the ring and with the fire button can perform various moves. When in a grapple the joystick needs to be waggled fast to throw the opponent onto the floor. Once the opponent is on the floor then it can be pinned.' FROM games WHERE igdb_id = 41022 ON CONFLICT (game_id, language_code) DO NOTHING;
