INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('wizards-and-warriors-iii-kuros-visions-of-power', 48092, '1992-04-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6oym.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc7mys.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wizards & Warriors III: Kuros - Visions of Power', 'When Kuros last did battle with the Evil Wizard Malkil atop Icefire Mountain, he raised his Ironsword in triumph and glory... or so he thought. Suddenly, a powerful bolt of magic has robbed Kuros of his armor, memory, and honor. But the distant presence of evil stirs in his mind, leading him to the once fair city of Piedup, the very same place where the villainous soul of Malkil survives. Without his armor, Kuros will need crafty disguises to travel undetected, ready to do battle as a wizard, nobleman or thief. His quest will take him from the depths of the dungeon to the palace containing riches beyond belief - building strength, perfecting fighting skills and acquiring rare knowledge of magic along the way. The time has come for Kuros to turn his visions of power... into reality!' FROM games WHERE igdb_id = 48092 ON CONFLICT (game_id, language_code) DO NOTHING;
