INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dogyuun', 'It is a science-fiction top down shooter in which the player controls bomber space fighter crafts called Sylfers. The player is provided with a main weapon - a laser beam which can be upgraded to a lightning beam. There are two slots for additional upgrades that can be attached to the ship. The first one is for a bomb module and the second one is for a speed module.' FROM games WHERE igdb_id = 91482 ON CONFLICT (game_id, language_code) DO NOTHING;
