INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jill Saves the Prince', 'Jill of the Jungle 3 is part of the Jill of the Jungle trilogy released by Epic MegaGames. The entire trilogy was released in 1992 exclusively for PC DOS, each sold separately. A year later, the three games were combined into Jill of the Jungle: The Complete Trilogy. Although none of the games were particularly well received, the revenue and attention was enough to enable MegaGames to continue to produce larger titles, most notably their successful Unreal series of games.' FROM games WHERE igdb_id = 9645 ON CONFLICT (game_id, language_code) DO NOTHING;
