INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bazooka Blitzkrieg', 'Bazooka Blitzkrieg game made for the SNES Super Scope. It featured a bleak modern setting filled with cyborgs and various bosses including a large flying warship a tank, and various others. The primary button fired regular machine gun rounds, and the thumb button fired rockets. Released in 1992 by Bandai.' FROM games WHERE igdb_id = 42627 ON CONFLICT (game_id, language_code) DO NOTHING;
