INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bills-tomato-game', 14306, '1992-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cbb7yl5dkqdkhyn0gpad.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc6l5a.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bill''s Tomato Game', 'Meet Terry and Tracy, an everyday pair of walking, talking tomatoes caught up in a totally unfeasible tale of rivalry, evil squirrels and mystical lands... oh and, erm, love! Ingredients Tracy and Terry are the cream of the tomatoes. Apart from being particularly ripe and squashy specimens, they''re both in love and determined to escape from the lorry taking them to the Puree factory so they can run away together and get married. And so, after being hurled into the back of the delivery truck, they make their move, slipping quietly out of the back and squopping (animals hop, tomatoes squop!) away to happiness. Whatever could go wrong? Well, as it happens, lurking in the trees along their path, an evil squirrel was eying up Tracy''s plumb form and decided to take her for his own. Just as the two love birds were passing by a tall vine, the squirrel struck, whisking Tracy away from Terry and carrying her away to his vine-top abode. Terry saw red. His skin puckered and his little crown of leaves trembled with anger. So, off he dashed in pursuit of the rascally rodent to win back his sweetheart... And you thought tomatoes couldn''t climb trees.' FROM games WHERE igdb_id = 14306 ON CONFLICT (game_id, language_code) DO NOTHING;
