INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('f1-circus-92', 37714, '1992-12-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6xei.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'F1 Circus ''92', 'A Formula One racing game for the PC Engine. The last of the F1 Circus games to be released for the system. F1 Circus ''92, sometimes known as F1 Circus ''92: The Speed of Sound, is a racing game for the PC Engine and part of Nichibutsu''s F1 Circus series. It is the fourth and last game in the series to be released on the PC Engine platform, and the seventh game in the series overall. Like its predecessors, it is officially licensed by the distributors of Formula One in Japan, and also has the rights to use the real names of teams/drivers. The game again focuses on top-down races that move at great speed and require a lot of memorization and careful driving. The player can easily be forced to retire from the race early if they take too much damage from collisions with the walls or other drivers. There''s a strong customization element as well, and the player can choose to play a Special mode that includes dialogue with NPCs between races.' FROM games WHERE igdb_id = 37714 ON CONFLICT (game_id, language_code) DO NOTHING;
