INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Black Crypt', 'Black Crypt is a role-playing video game. It was Raven Software''s debut title, and was published for the Amiga by Electronic Arts in 1992. Its 3D realtime style is similar to FTL Games'' popular Dungeon Master, where the player leads a party of four heroes through a large dungeon to ultimately confront and defeat a powerful enemy. A version for the Sega Mega Drive was in development, but never released.' FROM games WHERE igdb_id = 8692 ON CONFLICT (game_id, language_code) DO NOTHING;
