INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'River City Renegade', 'A student-only electric train has departed from Tokyo Station and has passed through Kyoto Station. A group of sophomore students from Nekketsu High School led by Kunio are aboard that train. Their destination is the city of laughter and defraud, Osaka. Kunio is sleepy and tired and that''s when Hiroshi''s voice wakes him up. "Kunio! Yoshihiro will guide us throught Osaka! Come with us!"(Yoshihiro is an exchange student who came from Osaka) Kunio has just learn that he is in Osaka.' FROM games WHERE igdb_id = 42427 ON CONFLICT (game_id, language_code) DO NOTHING;
