INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ultra Baseball Jitsumei-ban', 'Ultra Baseball Jitsumei-ban is a baseball simulator from Culture Brain and part of their Ultra Baseball series of games, which take a slightly more surreal route than other baseball franchises by giving players special abilities to use. The first two games in the series are better known in the US as Baseball Simulator 1.000 and Super Baseball Simulator 1.000. Jitsumeiban means "Real Player Version", due to the game being officially licensed by Nippon Professional Baseball, which allowed them to use actual team and player names. There would eventually be two more Ultra Baseball Jitsumeiban games for the Super Famicom, released in 1994 and 1995.' FROM games WHERE igdb_id = 44429 ON CONFLICT (game_id, language_code) DO NOTHING;
