INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dr. Livingstone, I Presume?', 'In this educational game from MECC the player travels through Africa in the place of an ill Henry Morton Stanley in search of Dr. Livingstone. The player runs into several native African tribes and learns of their cultures, their trade preferences, and how to manage a team of porters that aid in the search. There are also many geographical aspects to the game, such as learning about Africa''s major rivers, lakes, swamps, mountain ranges, etc.' FROM games WHERE igdb_id = 127480 ON CONFLICT (game_id, language_code) DO NOTHING;
