INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dead Connection', 'Dead Connection is an arcade game released by Taito in 1992. The game takes place on September 5, 1953 "in a big city somewhere". It features a group of detectives who set out to fight a crime family. The game has a strong Film noir vibe, shown through the appearance of the detectives and the featuring of a female protagonist. Each stage is preceded by a short cinematic interlude that explains the transition between the game''s different locales.' FROM games WHERE igdb_id = 39635 ON CONFLICT (game_id, language_code) DO NOTHING;
