INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chase H.Q. II', 'Similar to Chase H.Q. in this sequel you drive on a freeway trying to catch up with five criminals who have committed felonies, with time against you. You can choose one of three vehicles to drive: a sports car, 4-wheel drive, and a semi truck. Each one of them having their advantages and disadvantages.' FROM games WHERE igdb_id = 304296 ON CONFLICT (game_id, language_code) DO NOTHING;
