INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'F-1 Grand Prix', 'F-1 Grand Prix is a 1991 Formula One-based arcade racing video game developed and published by Video System exclusively in Japan. It is the first title in Video System''s licensed F1 Grand Prix series, which this title is based on the 1991 Formula One season. It was licensed by Fuji Television and FOCA. The arcade game was later ported to the Super Famicom exclusively in Japan on April 28, 1992.' FROM games WHERE igdb_id = 46837 ON CONFLICT (game_id, language_code) DO NOTHING;
