INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fighter & Attacker', 'Fighter & Attacker, originally titled F/A in Japan, is a vertical scrolling shooter arcade game, which was released by Namco in 1992. The game runs on Namco NA-1 hardware, was the first game on this hardware to be released outside Japan (Bakuretsu Quiz Ma-Q Dai Bōken was the first overall) and is the only game from the company that showed the Federal Bureau of Investigation''s "Winners Don''t Use Drugs" screen in its attract sequence with vertical orientation (the two titles that displayed it previously, Tank Force and Steel Gunner 2, both displayed it with horizontal orientation).' FROM games WHERE igdb_id = 39922 ON CONFLICT (game_id, language_code) DO NOTHING;
