INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NFL Sports Talk Football ''93 Starring Joe Montana', 'NFL Sports Talk Football ''93 is an American football video game featuring Joe Montana, released in 1992. It is the third in the series, and the first to be licensed by the National Football League. Features include in-game commentary generated from a bank of pre-recorded dialogue (courtesy of Lon Simmons), up to 50 different plays, dynamic zoom-in camera views and official team names.' FROM games WHERE igdb_id = 72117 ON CONFLICT (game_id, language_code) DO NOTHING;
