INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('stanley-the-search-for-dr-livingston', 48242, '1992-10-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6ow9.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stanley: The Search for Dr. Livingston', 'DANGER Danger lurks behind every turn and every tree as you seek out the ancient temple of wisdom, the legendary lost temple of "Am-Zutuk" while hot on the trail of the absent-minded Dr. Livingston deep in the heart of the mysterious Congo jungle. ADVENTURE Adventure overtakes you as you battle under mountain and over hill against cunning natives, giant spiders and psychedelic specters. Discover hidden items and maps; recover lost ancient weapons and armor. EXPLORE Explore dark mysterious caverns and brave hundreds of levels of uncharted wilderness as you risk your life for fame, wisdom and adventure. Hurry, find the lost Dr. Livingston and the mysterious temple. Who knows, your exploits may someday be famous. Dr. Livingston I presume? Special password feature included!' FROM games WHERE igdb_id = 48242 ON CONFLICT (game_id, language_code) DO NOTHING;
